/* chronicle data chunk: cn-12 | 清 1644–1839 | 拆分自 cn-05（原片 352KB 超 320KB 上限），切点 1644 年 | 生成于 2026-09-21 */
window.__CHRONICLE_CHUNK = window.__CHRONICLE_CHUNK || {};
window.__CHRONICLE_CHUNK["cn-12"] = [
  { id: "cn--1644--m01", track: "cn", year: 1644, yearApprox: false, dim: "military", weight: 4, title: "山海关一片石之战", summary: "吴三桂降清，多尔衮破大顺军入京。", detail: { background: "李自成入北京后，招降山海关吴三桂未成，掠其家；三桂西走，遣使向盛京求师。", process: "1644年（顺治元年）四月二十二日，多尔衮率八旗兵驰至山海关外一片石，乘大顺军疲惫风起之际冲击其阵，李自成败退永平；五月初二清军入京师。", impact: "关宁军与八旗合流使北方兵力对比一举逆转，清以替明复仇之名取得北京，此后二十年南方战事随之全面展开。", figures: ["多尔衮","吴三桂","李自成"], place: "山海关—一片石（今河北秦皇岛—辽宁绥中）", state: "清／大顺", sources: ["《清世祖实录》卷四","《明季北略》","魏斐德《洪业：清朝开国史》"], tags: ["山海关","入关"] }, related: ["cn--1644--p01", "cn--1644--p02", "world--1644--p01"] },
  { id: "cn--1644--p01", track: "cn", year: 1644, yearApprox: false, dim: "politics", weight: 5, title: "甲申之变明亡", summary: "李自成入京师，崇祯帝自缢万岁山。", detail: { background: "1644年正月李自成在西安建国号大顺，二月东征，连陷太原、大同、宣府，明边镇将吏多降。", process: "三月十八日外城陷，内监开门迎降；十九日晨李自成军入内城，思宗朱由检登万岁山自缢，太监王承恩陪死，皇后自尽，太子与定、永二王南奔。", impact: "延续二百七十六年的明中央政权告终；山海关的吴三桂转而降清，为多尔衮入关提供钥匙，中国进入清、大顺、南明三方角逐期。", figures: ["李自成","朱由检","吴三桂","王承恩"], place: "北京—西安", state: "明／大顺", sources: ["《明史·庄烈帝本纪》","《甲申传信录》","《怀陵流寇始终录》"], tags: ["甲申","明亡"] }, related: ["cn--1643--p01", "cn--1641--d01", "world--1644--p01"] },
  { id: "cn--1644--p02", track: "cn", year: 1644, yearApprox: false, dim: "politics", weight: 3, title: "清迁都定鼎京师", summary: "十月奉幼帝入燕，以明制治天下。", detail: { background: "多尔衮纳洪承畴、范文程之议，以北都扼天下之吭，迁都之议遂定。", process: "1644年（顺治元年）十月初一，六岁的福临至京师，初四祭告天地于南郊，诏定鼎燕京；仍六部、内三院、都察院之制，征明遗官，开科取士，为降附者录衔。", impact: "清由此从东北政权转为接管全国的中央政权，其官制、科举、赋役大体沿明之旧，减少了北中国的抵抗。", figures: ["福临","多尔衮","范文程","洪承畴"], place: "京师（今北京）", state: "清", sources: ["《清世祖实录》卷九","《东华录》","《明季北略》"], tags: ["定鼎","官制"] }, related: ["cn--1644--m01"] },
  { id: "cn--1644--p03", track: "cn", year: 1644, yearApprox: false, dim: "politics", weight: 3, title: "大西政权建都成都", summary: "张献忠称帝西川，铸钱设官。", detail: { background: "张献忠自湖广入川，重庆、成都相继陷，明蜀王府积赀巨万为其所有。", process: "1644年（顺治元年）十一月，张献忠即皇帝位于成都，国号大西，建元大顺，铸大顺通宝，以孙可望、李定国、刘文秀、艾能奇为将军，分兵四路。", impact: "明末清初四川人口锐减由兵事、饥荒、瘟疫与虎患数因并发，清人笔记与《明史》所载死者数字被现代人口史研究视为明显夸大。", figures: ["张献忠","孙可望","李定国"], place: "成都（今四川成都）", state: "大西／明", sources: ["《明史·张献忠传》","《蜀碧》","曹树基《中国人口史》第四卷"], tags: ["大西","四川"] }, related: ["cn--1646--m02"] },
  { id: "cn--1645--i01", track: "cn", year: 1645, yearApprox: false, dim: "institution", weight: 3, title: "圈地令与投充法", summary: "以无主之名夺近京田，投充为奴。", detail: { background: "八旗兵丁东来，需田土粮栈；有司以近京州县无主荒地为名清丈。", process: "1644年十二月（1645年1月）首下圈地之令，顺治四年、五年再圈，凡河间、永平、保定等近京州县民地，不论有无主，多被圈给旗人，民田被夺者以「地去而粮犹在」为苦；同年定投充法，贫民以此求自全，豪强因之影占。", impact: "圈地与投充在直隶造成数万顷田土易主与数万人口入旗，成为康熙中停圈、清厘旗地诸政的起因。", figures: ["多尔衮","何洛会"], place: "顺天、永平、河间、保定诸府", state: "清", sources: ["《清世祖实录》卷四九","《八旗通志·土田志》","《东华录》"], tags: ["圈地","旗地"] }, related: ["cn--1644--p02"] },
  { id: "cn--1645--m01", track: "cn", year: 1645, yearApprox: false, dim: "military", weight: 4, title: "扬州城破与屠城", summary: "史可法死守，清军破城后大掠。", detail: { background: "1645年春清豫亲王多铎南下，扬州为江北屏障；督师史可法请兵不应。", process: "四月二十五日清军以红衣炮破扬州，史可法被执不屈死；多铎命屠城，《扬州十日记》记十日之内死者八十万，近世学者据明代扬州户口与城周重推，多认为实际死者在数万至二十万之间，数字虽异而屠城之事为诸书所同载。", impact: "扬州之屠使江南士民震动，弘光朝廷旋即瓦解，清廷以残破示警的手段在江浙、福建、广东反复奏效。", figures: ["多铎","史可法"], place: "扬州（今江苏扬州）", state: "清／南明", sources: ["《明史·史可法传》","《扬州十日记》（作者与数字真伪有争议）","《小腆纪年》","魏斐德《洪业：清朝开国史》"], tags: ["扬州","屠城"] }, related: ["cn--1645--p01", "world--1645--m01"] },
  { id: "cn--1645--m02", track: "cn", year: 1645, yearApprox: false, dim: "military", weight: 3, title: "江阴八十一日", summary: "典史阎应元守城，旬日不下。", detail: { background: "剃发令至江南，江阴以「头可断，剃发不可」拒令，逐命官，推典史阎应元、陈明遇主守。", process: "1645年（顺治二年）六月二十五日起守城，前降将刘良佐、李成栋偕清贝勒博洛迭攻，八月二十一日城陷；阎应元赴水不屈被杀，城破后屠戮，《江阴城守纪》所记存者仅五十三人，县志与近人考订认为数字过当。", impact: "一座县城以八十余日的抵抗把剃发令的代价具体化，此后江南抗清多以江阴为号，清廷在东南的征敛与安抚由此并进。", figures: ["阎应元","陈明遇","博洛"], place: "江阴（今江苏江阴）", state: "清", sources: ["《江阴县志》","《江阴城守纪》","《小腆纪年》"], tags: ["江阴","抗清"] }, related: ["cn--1645--p01"] },
  { id: "cn--1645--m03", track: "cn", year: 1645, yearApprox: false, dim: "military", weight: 3, title: "嘉定三屠", summary: "以拒剃发起事，一县三次被屠。", detail: { background: "1645年六月剃发令下，嘉定士民以布衣举兵，杀清所命官吏，四乡响应。", process: "1645年（顺治二年）六月、七月、闰六月间，明遗绅侯峒曾、黄淳耀与朱瑛等三度聚守，李成栋部三次入城屠掠，鸡犬不留之语见于当时记述；死事者数万，黄淳耀自经，侯峒曾投水。", impact: "嘉定之例说明清初江南的抵抗多由一项身体政策触发，也促成此后士人隐居不仕、以文字寄哀的普遍心态。", figures: ["侯峒曾","黄淳耀","李成栋"], place: "嘉定（今上海市嘉定区）", state: "清", sources: ["《嘉定县志》","《研堂见闻杂记》","《明季南略》"], tags: ["嘉定","屠城"] }, related: ["cn--1645--p01"] },
  { id: "cn--1645--p01", track: "cn", year: 1645, yearApprox: false, dim: "politics", weight: 5, title: "颁剃发令", summary: "限十日尽行剃发，违者以军法从事。", detail: { background: "清初入关本许易服剃发旋止；南京降后，汉臣与降官之议复起。", process: "1645年（顺治二年）六月十六日诏，京城内外限十日、各省自诏书到日限十日，官民尽剃发梳辫，诏称「遵依者为我国之民，迟疑者同逆命之寇」；江南以剃发复起兵者处处蜂起。", impact: "一项发式之令把文化羞辱变成生死抉择，使江阴、嘉定、浙闽的抵抗与屠杀连锁发生，也奠定清代二百六十年的男子形貌。", figures: ["福临","多尔衮","洪承畴"], place: "京师及各行省", state: "清", sources: ["《东华录》顺治朝","《明季南略》","顾诚《南明史》"], tags: ["剃发令","民族政策"] }, related: ["cn--1645--m01"] },
  { id: "cn--1646--i01", track: "cn", year: 1646, yearApprox: false, dim: "institution", weight: 3, title: "丙戌科首行会试", summary: "清初开科取士，状元傅以渐。", detail: { background: "定鼎京师后，为收揽士心、储备官僚，礼部请以顺治二年行乡试、次年会试。", process: "1646年（顺治三年）首行丙戌科会试、殿试，傅以渐为状元，中式者四百名，仍八股文、试帖诗、策五道之制；直隶、各省及新附州县并行乡试。", impact: "科举的迅速恢复使北方士大夫重得入仕之途，为清廷取得行政人才，也把经义程式一直延续到1905年。", figures: ["傅以渐","冯铨"], place: "京师贡院（今北京）", state: "清", sources: ["《清世祖实录》卷五一","《明清进士题名碑录索引》","商衍鎏《清代科举考试述录》"], tags: ["科举","会试"] }, related: ["cn--1313--s01"] },
  { id: "cn--1646--m01", track: "cn", year: 1646, yearApprox: false, dim: "military", weight: 3, title: "仙霞关破，隆武帝死", summary: "清取浙闽，鲁王出海，绍武十日而亡。", detail: { background: "1645年弘光亡后，朱聿键称帝于福州（隆武），朱以海监国于绍兴，两家不相下。", process: "1646年（顺治三年）八月清贝勒博洛越仙霞关，衢州、福州继下，隆武帝被俘于汀州，绝食死；同年十二月清取广州，绍武政权自建立至覆亡凡四十日，大学士苏观生死之。", impact: "南明在浙闽的朝廷相继瓦解，永历一系转入西南，清廷则取得福建海岸，为日后的迁海与用台政策预设地理。", figures: ["博洛","朱聿键","朱以海"], place: "仙霞关—福州—汀州（今浙江—福建）", state: "清／南明", sources: ["《小腆纪年》","温睿临《南疆逸史》","《清史稿·博洛传》"], tags: ["隆武","仙霞关"] }, related: ["cn--1646--p01"] },
  { id: "cn--1646--m02", track: "cn", year: 1646, yearApprox: false, dim: "military", weight: 3, title: "西充之役张献忠殁", summary: "降将乡导，一矢而大西政权瓦解。", detail: { background: "张献忠自川北盐亭、梓潼北走，与明降将所导之清军相持，部众苦其刑，孙可望、李定国分据州县。", process: "1646年（顺治三年）十一月，肃亲王豪格率军追击，献忠养子刘进忠先已降清、为其乡导，西充凤凰山一役献忠中矢死，年四十七；孙可望、李定国遂南走云南。", impact: "大西军余部入云贵后拥立永历，成为1650年代抗清的主力，云南由此成为南明最后的根据地。", figures: ["张献忠","豪格","刘进忠","李定国"], place: "西充凤凰山（今四川南充）", state: "清／大西", sources: ["《明史·张献忠传》","《蜀碧》","《明季南略》"], tags: ["大西","西充"] }, related: ["cn--1644--p03"] },
  { id: "cn--1646--p01", track: "cn", year: 1646, yearApprox: false, dim: "politics", weight: 2, title: "永历帝即位肇庆", summary: "最末的明廷立国，旋走西南。", detail: { background: "隆武政权亡后，两广残明官员需一宗主；桂王朱由榔以万历之孙，为丁魁楚、瞿式耜等所拥。", process: "1646年（顺治三年）十一月，朱由榔即皇帝位于肇庆，改元永历，以丁魁楚、瞿式耜入阁，旋走梧州；此后十年转徙广西、贵州、云南，1651年后依孙可望于安龙。", impact: "永历一朝自1646延至1662，为南明延续最久者；其与郑氏、大西军余部的联合与内耗，构成1650年代抗清战局的主线。", figures: ["朱由榔","瞿式耜","丁魁楚"], place: "肇庆（今广东肇庆）", state: "南明", sources: ["《永历实录》","温睿临《南疆逸史》","顾诚《南明史》"], tags: ["永历","南明"] }, related: ["cn--1646--m01"] },
  { id: "cn--1647--i01", track: "cn", year: 1647, yearApprox: false, dim: "institution", weight: 3, title: "《大清律集解附例》成", summary: "以《大明律》为蓝定做清律。", detail: { background: "入关后刑名无所凭，议者请参用明律与国初之制。", process: "约1646至1647年间（顺治三、四年）《大清律集解附例》成而颁行，以《大明律》篇目为骨，分六律四百余条，附入满汉合议之例与八旗治罪之条。", impact: "清代成文法体系由此定形，其后康熙、雍正、乾隆三朝修律皆在此本上增例，是中国最后一代传统法典的起点。", figures: ["刚林","党崇雅"], place: "京师（今北京）", state: "清", sources: ["《大清律集解附例》顺治刊本","《清史稿·刑法志》","《清世祖实录》卷六三"], tags: ["法典","律例"] }, related: ["cn--1644--p02"] },
  { id: "cn--1648--p01", track: "cn", year: 1648, yearApprox: false, dim: "politics", weight: 3, title: "金声桓李成栋反正", summary: "江西、广东一夜归明，西南战局重启。", detail: { background: "明将金声桓、李成栋先降清，攻取江西、广东，而后以赏薄、裁抑为怨。", process: "1648年（顺治五年）正月金声桓以南昌归明，二月李成栋以广东反正，奉永历正朔，江南震动；清以谭泰、何洛会围南昌，1649年二月城破，金声桓赴水死，李成栋旋溺死于粤东。", impact: "两省反正使清廷在南方的统治几乎崩解，也暴露降将拥兵自重的结构性问题；此后降将之权被逐步削夺。", figures: ["金声桓","李成栋","王得仁","谭泰"], place: "南昌—广州", state: "清／南明", sources: ["《清史稿·谭泰传》","《小腆纪年》","温睿临《南疆逸史》"], tags: ["反正","江西"] }, related: ["cn--1646--p01"] },
  { id: "cn--1650--m01", track: "cn", year: 1650, yearApprox: false, dim: "military", weight: 3, title: "广州城破与屠城之案", summary: "尚可喜围十月，破后杀戮累日。", detail: { background: "李成栋死后广东复归清，孙可望、李定国屡攻之；清以尚可喜、耿仲明统汉军南下。", process: "1650年（顺治七年）十一月平南王尚可喜、靖南王耿继茂克广州，围城凡十月，城内外食尽；破后戮其抗者，《广东通志》与在粤耶稣会士书信并记死者自七万至十万不等，现代学者据顺治间广东户口推定实际当以数万计。", impact: "广州之屠使岭南士商远避，澳门与荷兰的交涉因此紧张；清廷在广东的税基与海商网络迟至1680年代方才恢复。", figures: ["尚可喜","耿继茂"], place: "广州（今广东广州）", state: "清", sources: ["《（康熙）广东通志》","《小腆纪年》","在粤耶稣会士书信集","魏斐德《洪业：清朝开国史》"], tags: ["广州","屠城"] }, related: ["cn--1648--p01"] },
  { id: "cn--1651--p01", track: "cn", year: 1651, yearApprox: false, dim: "politics", weight: 2, title: "世祖亲政追论睿亲王", summary: "多尔衮夺谥，顺治帝收权。", detail: { background: "1650年十二月多尔衮死于喀喇城，追尊义皇帝、葬于冢，位极震主；老臣郑亲王济尔哈朗已病，两黄旗旧臣分布朝中。", process: "1651年（顺治八年）正月世祖年十四亲政；二月追论多尔衮谋逆，削谥、仆其墓碑、籍其家，亲信何洛会等伏诛，以济尔哈朗等任咨询，宗室不得专权之禁自此立。", impact: "摄政体制终结，皇权复归；八旗内部的两黄、两白旧怨被清洗，也为此后不任亲王摄政的家法留下警戒。", figures: ["福临","多尔衮","济尔哈朗","何洛会"], place: "京师（今北京）", state: "清", sources: ["《清世祖实录》卷六〇","《东华录》顺治朝","《清史稿·睿忠亲王传》"], tags: ["睿亲王","亲政"] }, related: ["cn--1644--p02"] },
  { id: "cn--1652--m01", track: "cn", year: 1652, yearApprox: false, dim: "military", weight: 3, title: "李定国两蹶名王", summary: "桂林、衡州一战而清二王死。", detail: { background: "孙可望、李定国拥永历入云南，1652年出师北伐，取贵州、湖南。", process: "1652年（顺治九年）七月定南王孔有德困桂林，力战败，举室自焚，清失广西；十一月敬谨亲王尼堪率军至衡州，中伏阵亡，清军北撤。", impact: "自1645年以来南明最盛之一刻，清廷几欲弃十八省之外；内讧随之而来，1656年孙可望兵败降清，西南大局逆转。", figures: ["李定国","孔有德","尼堪","孙可望"], place: "桂林—衡州（今广西—湖南）", state: "清／南明", sources: ["《永历实录》","《清史稿·孔有德传》","《小腆纪年》"], tags: ["李定国","西南"] }, related: ["cn--1646--m02"] },
  { id: "cn--1659--m01", track: "cn", year: 1659, yearApprox: false, dim: "military", weight: 3, title: "清军入滇，永历走缅甸", summary: "三路会攻昆明，明室西奔。", detail: { background: "1657年孙可望兵败降清，具言西南虚实；清以洪承畴经略湖广、川、陕、云贵，命吴三桂、赵布泰等分路进师。", process: "1659年（顺治十六年）正月，吴三桂率师克云南，李定国塔子山、玉龙关之战失利，焚昆明而西；永历帝由腾越入缅甸，李定国退孟艮、磨黑山。", impact: "南明陆上抗清的最后根据地丧失，残余力量转入缅甸与沿海郑氏一线；清廷在西南土司地带设流官、兴屯政，改土归流随之展开。", figures: ["吴三桂","李定国","朱由榔"], place: "云南—缅甸阿瓦", state: "清／南明", sources: ["《清史稿·吴三桂传》","《永历实录》","顾诚《南明史》"], tags: ["入滇","缅甸"] }, related: ["cn--1662--p01"] },
  { id: "cn--1661--m01", track: "cn", year: 1661, yearApprox: false, dim: "military", weight: 3, title: "郑成功渡海围大员", summary: "自鹿耳门入，断热兰遮之水。", detail: { background: "郑成功以金门、厦门为基地而兵饷日绌，采降郑之荷属通事何斌计，取台湾为王业；荷兰大员守军仅千余，赤嵌、热兰遮两城相望。", process: "1661年（永历十五年）四月初二，郑军自鹿耳门浅道入台江，先逼普罗民遮城，守将猫难实叮出降；五月合围热兰遮城，断其水道，荷兰巴达维亚援军八月至，被逐出外海。", impact: "汉人武装第一次自欧洲殖民者手中取得据点，台湾进入明郑时期；郑氏设府县、召佃屯田，把闽南的地权与租佃关系移植到岛上。", figures: ["郑成功","揆一","何斌"], place: "大员—赤嵌（今台湾台南）", state: "明郑／荷兰", sources: ["杨英《先王实录》","《热兰遮城日志》","江日升《台湾外纪》"], tags: ["台湾","郑氏"] }, related: ["cn--1662--m01"] },
  { id: "cn--1661--p01", track: "cn", year: 1661, yearApprox: false, dim: "politics", weight: 3, title: "世祖崩，四臣辅政", summary: "遗命玄烨八岁即位，异姓大臣辅政。", detail: { background: "1661年正月世祖以痘疮崩于养心殿，年二十四；遗诏多引罪之语，而言官与诸王不得入宫之禁同时议定。", process: "顺治十八年正月，遗诏立皇第三子玄烨（八岁）即位，以索尼、苏克萨哈、遏必隆、鳌拜四内大臣辅政，不由宗室摄政，诸非诏命不得入御内。", impact: "辅政体制取代摄政亲王之制，把幼主的权力交给异姓勋臣；鳌拜遂得兼制皇权，至1669年圣祖设计乃解，清代不再设辅政之局由此决定。", figures: ["福临","玄烨","索尼","鳌拜"], place: "京师（今北京）", state: "清", sources: ["《清圣祖实录》卷一","《东华录》顺治朝","《清史稿·索尼传》"], tags: ["辅政","康熙"] }, related: ["cn--1669--p01"] },
  { id: "cn--1661--p02", track: "cn", year: 1661, yearApprox: false, dim: "politics", weight: 4, title: "迁海令徙沿海居民", summary: "三十里内尽徙，片板不许下水。", detail: { background: "郑成功以厦门、金门为抗清基地，1661年北围南京之役虽败，东南海面仍为其所有；清议者主坚壁清野以绝其粮食、铁器。", process: "1661年（顺治十八年）六月下迁海之令：直隶、山东、江南、浙江、福建、广东沿海居民尽内徙三十里，立界碑、毁庐舍田畴，片板不许入海；有司以迁界迟缓获罪，督抚以界外不任责。", impact: "东南沿海数千里沃野成为界外荒地，渔民失所者无算；至1669年部分展界与1684年开海才逐渐恢复，其对海上贸易与沿海市镇的破坏延续近三十年。", figures: ["玄烨","鳌拜","达哈他"], place: "直隶至广东沿海", state: "清", sources: ["《清史稿·食货志》","《东华录》顺治朝","《（康熙）福建通志》"], tags: ["迁海","海禁"] }, related: ["cn--1661--m01"] },
  { id: "cn--1662--c01", track: "cn", year: 1662, yearApprox: false, dim: "culture", weight: 4, title: "《明夷待访录》成", summary: "以天下为主君为客，论限制君权。", detail: { background: "黄宗羲父廕为东林党人所杀，本人起兵于鲁王幕下，抗清失败后归乡讲学于浙东。", process: "1662年（康熙元年）成《明夷待访录》，凡二十一篇，斥「为天下之大害者君而已矣」，主天下为主、君为客，提出学校议政、方镇分权、重定田赋、工商皆本诸议。", impact: "传统政治思想中对君主制度最系统的一次批判，清代列为禁毁；1900年代经梁启超、黄遵宪等重印，成为立宪与革命两派共用的思想资源。", figures: ["黄宗羲"], place: "余姚（今浙江宁波余姚）", state: "清", sources: ["《明夷待访录》","《宋元学案》","《清史稿·儒林传》"], tags: ["政治思想","黄宗羲"] }, related: ["cn--1695--f01"] },
  { id: "cn--1662--m01", track: "cn", year: 1662, yearApprox: false, dim: "military", weight: 4, title: "荷将出降，郑氏建政台湾", summary: "围城九月，热兰遮竖旗降。", detail: { background: "郑军断其水源粮道，荷人守城者病死战死过半，大员长官揆一待援不至。", process: "1662年（康熙元年、永历十六年）二月，揆一竖白旗出降，偕其属员、兵丁携人物东归巴达维亚；郑成功以赤嵌为承天府，划东都明坊，设官屯田。五月成功卒于东都，年三十九，子郑经嗣位。", impact: "荷兰在近华的领土统治告终，郑氏据台湾续奉永历正朔、铸永历通宝，与日本、荷兰、暹罗维持转口贸易，至1683年施琅平台而亡。", figures: ["郑成功","揆一","郑经"], place: "承天府（今台湾台南）", state: "明郑", sources: ["杨英《先王实录》","《（康熙）台湾府志》","《热兰遮城日志》"], tags: ["台湾","明郑"] }, related: ["cn--1661--m01", "cn--1683--m01"] },
  { id: "cn--1662--p01", track: "cn", year: 1662, yearApprox: false, dim: "politics", weight: 3, title: "永历帝死于昆明", summary: "缅甸交人，篦子坡同太子皆缢。", detail: { background: "1659年永历帝入缅甸，居阿瓦；1661年缅臣杀明从官多人（咒水之难），吴三桂以大军临境索人。", process: "1662年（康熙元年）正月缅王以舆轿送永历至清军；四月十五日（6月1日）云南巡抚朱国治奉命，缢永历帝及皇太子于昆明篦子坡，从官死者数十人。", impact: "明统至此而绝，郑氏在台湾犹奉其正朔；清廷旋以云贵为吴三桂藩属地，其兵、财、官自辟，三藩之患已成。", figures: ["朱由榔","吴三桂","朱国治"], place: "昆明（今云南昆明）", state: "清", sources: ["《永历实录》","刘湘客《求野录》","《清史稿·吴三桂传》"], tags: ["永历","明亡"] }, related: ["cn--1659--m01"] },
  { id: "cn--1663--p01", track: "cn", year: 1663, yearApprox: false, dim: "politics", weight: 3, title: "庄氏《明史》案结", summary: "一字一罪，株戮及刻工流及千里。", detail: { background: "湖州富室庄廷鑨购得明相朱国祯《明史》稿，延名士续成崇祯朝事，于建州卫署与南明隆武、鲁监国年号直书不讳，尊明而黜清。", process: "1661年案发，1663年（康熙二年）结案：庄廷鑨已死，戮其棺；作序、参订、校阅、刻工、书商及买书不举者凡七十余人处死，妻子流徙宁古塔；未举发之地方官同日伏诛。", impact: "清初第一起大文字狱，江浙士人受创最深；此后著述避忌时事、遁入名物考据，乾嘉汉学之风气与此有渊源。", figures: ["庄廷鑨","朱国祯"], place: "湖州—京师（今浙江—北京）", state: "清", sources: ["《东华录》康熙朝","《明史辑略》","孟森《明清史论著集刊》"], tags: ["文字狱","史案"] }, related: ["cn--1662--c01"] },
  { id: "cn--1664--c01", track: "cn", year: 1664, yearApprox: false, dim: "culture", weight: 3, title: "杨光先历狱起", summary: "以排耶之说逐西洋人，历法几乱。", detail: { background: "汤若望掌钦天监十余年，专用西洋新法定《时宪历》；回回科旧法与士大夫之怨久积。", process: "1664年（康熙三年）五月，回回科旧人杨光先上《请诛邪教疏》等，劾汤若望「私藏不反之书」、择定葬期惑众，宣称「宁可使中夏无好历法，不可使中夏有西洋人」；汤若望与南怀仁等下狱。1665年结案，汤若望等因京师地震得释旋卒，而福建设教士五人被处死，历法复用回回旧术。", impact: "西学在华的第一次全面失败；圣祖亲政后以南怀仁与回回科同测日影、验其胜乃重定历法，而礼仪之争与历狱并起，为百年后的教案先声。", figures: ["杨光先","汤若望","南怀仁"], place: "京师—杭州", state: "清", sources: ["杨光先《不得已》","《清圣祖实录》卷一二","魏特《汤若望传》"], tags: ["历狱","西学"] }, related: ["cn--1669--p01"] },
  { id: "cn--1668--d01", track: "cn", year: 1668, yearApprox: false, dim: "disaster", weight: 4, title: "郯城大地震", summary: "鲁南地震约八级半，城郭尽圮。", detail: { background: "郯城—庐江断裂带为华北东缘主要发震构造，沂州、莒州一带民居多土屋窑居。", process: "1668年7月25日（康熙七年六月十七日戌时）郯城、沂州、莒县一带地大震，《中国历史强震目录》定其震级约8.5级；极震区城郭官署庙宇尽圮，地裂水涌、黑泉喷出，山崩壅河，《（乾隆）沂州府志》与各家笔记所记死亡自数千至十余万不等，现代学者据清初山东户口推定当以数万口上下。", impact: "此为东部中国有史以来最强的一次地震，清廷蠲免沂州等州县钱粮、发帑振济；其地表破裂与液化遗迹，至今为研究郯庐断裂活动性的历史依据。", figures: ["玄烨"], place: "郯城—沂州（今山东临沂—日照）", state: "清", sources: ["《（乾隆）沂州府志》","《郯城县志》","国家地震局《中国历史强震目录》"], tags: ["地震","郯城"] }, related: [] },
  { id: "cn--1669--p01", track: "cn", year: 1669, yearApprox: false, dim: "politics", weight: 3, title: "圣祖除鳌拜亲政", summary: "以布库戏少年，一夕收辅政大臣。", detail: { background: "四辅政之后索尼老病、遏必隆附鳌拜，苏克萨哈请归政即被构陷诛死；1667年圣祖虽亲政，鳌拜犹以佐命元勋把持兵部与议政王大臣会议。", process: "1669年（康熙八年）五月，圣祖以布库戏（摔跤）少年十余辈入宫侍，鳌拜不设备，遂扑执之下狱，议政王大臣会议定三十罪，夺官拘禁、旋死；其党班布尔善等伏诛，苏克萨哈昭雪。", impact: "皇权自勋臣之手收回，此后清代不设辅政、不任亲王入议内廷；南书房之设与撤藩之谋皆以是年为起点。", figures: ["玄烨","鳌拜","索额图"], place: "京师（今北京）", state: "清", sources: ["《清圣祖实录》卷二九","《东华录》康熙朝","《清史稿·鳌拜传》"], tags: ["鳌拜","亲政"] }, related: ["cn--1661--p01"] },
  { id: "cn--1670--c01", track: "cn", year: 1670, yearApprox: false, dim: "culture", weight: 3, title: "《日知录》初刻", summary: "顾炎武札记八卷行，考据开风气。", detail: { background: "顾炎武（1613—1682）自崇祯末即辑经史、舆地、赋役之札记，北游后益访金石、边塞、田亩之实。", process: "1670年（康熙九年）《日知录》初刻八卷行于时，其书以经术、治道、博闻为次，考订名物、田赋、科举、边防，多引本文而断以己意；炎武殁后由潘耒整理为三十二卷本，于1704年刊行。", impact: "开清代考据之门，其「经学即理学」之说不空谈心性而求证于经典与史志，直接启乾嘉诸儒。", figures: ["顾炎武","潘耒"], place: "昆山—金陵（今江苏）", state: "清", sources: ["《日知录》潘耒序","顾炎武《亭林文集》","《清史稿·儒林传》"], tags: ["考据","顾炎武"] }, related: ["cn--1682--f01"] },
  { id: "cn--1673--p01", track: "cn", year: 1673, yearApprox: false, dim: "politics", weight: 4, title: "撤藩令与三藩之乱起", summary: "三王并请撤，朝议许之，吴藩反。", detail: { background: "平西王吴三桂镇云南、平南王尚可喜镇广东、靖南王耿精忠镇福建，三藩兵饷岁耗帑银近二千万两，云贵之饷半于天下。", process: "1673年（康熙十二年）三月尚可喜以老归辽请撤所部，朝议许之；吴三桂、耿精忠不得已亦上疏辞藩以试探。十一月下诏并撤三藩，吴三桂杀所派将领拒命，称天下都招讨兵马大元帅，发布讨清檄文，湖南、四川将吏响应。", impact: "自1673至1681八年之间，云贵、东南、西北几无完卵，清廷以加饷、挪漕项支军，财政与八旗兵力俱受考验，汉人降王权力格局自此终结。", figures: ["玄烨","吴三桂","尚可喜","耿精忠"], place: "云南—京师（今昆明—北京）", state: "清", sources: ["《清史稿·吴三桂传》","《东华录》康熙朝","《平定三逆方略》"], tags: ["三藩","撤藩"] }, related: ["cn--1662--p01", "cn--1681--m01", "world--1673--p01"] },
  { id: "cn--1674--m01", track: "cn", year: 1674, yearApprox: false, dim: "military", weight: 3, title: "耿精忠王辅臣相继叛", summary: "闽、陕同时易帜，东南西北俱裂。", detail: { background: "吴三桂以「恢复明朝」为号，遣使结福建耿精忠与台湾郑经，又诱陕西提督王辅臣。", process: "1674年（康熙十三年）三月耿精忠反于福州，联郑经取漳、泉；五月王辅臣据平凉杀宁夏副都统响应三桂，秦晋震动；六月郑经渡海取澎湖、厦金之路尽为其有，清在东南与西北同时崩解。", impact: "清廷以图海招抚平凉、康亲王杰书由浙入福建分其势，1676年王辅臣、耿精忠相继降；三藩之乱由全面溃退转为以湖南为界的相持。", figures: ["耿精忠","王辅臣","郑经","图海"], place: "福州—平凉（今福建—甘肃）", state: "清", sources: ["《清史稿·耿精忠传》","《平定三逆方略》","《清史列传·王辅臣传》"], tags: ["三藩","陕西"] }, related: ["cn--1673--p01"] },
  { id: "cn--1677--s01", track: "cn", year: 1677, yearApprox: false, dim: "science", weight: 3, title: "靳辅陈潢治河", summary: "筑堤建闸、分水分沙，十年河复故道。", detail: { background: "明天启以来黄河屡决于苏北，夺运入海；1676年黄河大决，淮、黄并溢，漕运与高家堰俱危。", process: "1677年（康熙十六年）以安徽巡抚靳辅为河道总督，用布衣陈潢赞画：挑清江浦引河、筑拦黄坝与御黄坝、建归仁堤与泄水闸，于宿迁、桃源、清河之间筑堤束水，历八年而黄归故道、淮出清口。", impact: "漕运得以畅通，河费与海防之扰大减；其「束水攻沙、借清刷浑」之策承潘季驯之绪而更精，所成《治河方略》为清代河工准则，陈潢后以谤去官，河工之得失自此与朝议纠缠。", figures: ["靳辅","陈潢"], place: "清江浦—高家堰（今江苏淮安）", state: "清", sources: ["《清史稿·靳辅传》","靳辅《治河方略》","《（康熙）治河奏绩书》"], tags: ["河工","水利"] }, related: [] },
  { id: "cn--1678--p01", track: "cn", year: 1678, yearApprox: false, dim: "politics", weight: 2, title: "吴三桂称帝旋死", summary: "衡州建号大周，在位五月而殂。", detail: { background: "1677年清军取长沙，贝勒尚善、安远靖寇大将军多罗贝勒勒尔锦等压湖南，三桂之势已衰，乃以称帝自固。", process: "1678年（康熙十七年）三月，吴三桂于衡州称帝，国号大周，改元昭武，以衡州为定天府，封其将帅；八月二十一日病殂，年六十七，诸将秘不发丧，迎其孙世璠于云南嗣位，改元洪化。", impact: "称帝一举使其「恢复明朝」的号召破产，各省响应者随之解体；此后清军以湖南、广西、四川三路进逼云南，1681年昆明破而藩平。", figures: ["吴三桂","吴世璠"], place: "衡州（今湖南衡阳）", state: "周", sources: ["《清史稿·吴三桂传》","《平定三逆方略》","《东华录》康熙朝"], tags: ["吴三桂","大周"] }, related: ["cn--1673--p01", "world--1673--p01"] },
  { id: "cn--1679--a01", track: "cn", year: 1679, yearApprox: false, dim: "art", weight: 3, title: "《芥子园画传》初集刻成", summary: "画谱木刻套印，流传为习画之阶。", detail: { background: "李渔（1611—1680）寓金陵，筑芥子园，以卖文、刻书为业，其婿沈心友出所藏明代李流芳画课稿本。", process: "1679年（康熙十八年）请王概及其弟臬、杲因稿增辑为《芥子园画传》初集五卷，分山石、树法、皴法、范式诸门，木版多色套印，刊于金陵芥子园；其后二集（梅兰竹菊）、三集（花鸟）、四集（人物）相续而成。", impact: "自是成为习画的阶梯，并流传至日本、朝鲜与东南亚；其程式化的画法启蒙了几百年画工与业余画者，亦被批评为拘束写生之气。", figures: ["李渔","王概","沈心友"], place: "金陵（今江苏南京）", state: "清", sources: ["《芥子园画传》初集凡例","李渔《闲情偶寄》","《（道光）重订芥子园画传》"], tags: ["画谱","版画"] }, related: [] },
  { id: "cn--1679--d01", track: "cn", year: 1679, yearApprox: false, dim: "disaster", weight: 3, title: "三河平谷大地震", summary: "京师宫署多圮，诏廷臣直言。", detail: { background: "1679年9月2日（康熙十八年八月初七日酉时）直隶三河、平谷间地大震，京师宫署民舍多坏。", process: "《中国历史强震目录》定其震级约8级，极震区在三河、平谷之间，紫禁城宫殿、各部衙署与民居坏损以万计，《（康熙）三河县志》与官书所记死者自数千至上万不等；震后余震经年，通州、顺义地裂涌黑水。", impact: "圣祖以灾异诏廷臣直言时政得失，蠲顺天等属钱粮、发帑振济，并令修圮坏城署；此震为京师地区历史上有记录以来最强的一次。", figures: ["玄烨"], place: "三河—平谷（今北京东北部）", state: "清", sources: ["《（康熙）三河县志》","《清圣祖实录》卷八四","国家地震局《中国历史强震目录》"], tags: ["地震","京师"] }, related: [] },
  { id: "cn--1681--m01", track: "cn", year: 1681, yearApprox: false, dim: "military", weight: 3, title: "清军克昆明，三藩平", summary: "围城八月，吴世璠自杀。", detail: { background: "1680年清军取贵州、川南，赵良栋、彰泰等分路逼云南；洪化政权内部诸将相攻，兵疲食匮。", process: "1681年（康熙二十年）二月清军薄昆明，围城八月，城内人相食；十月城破，赵良栋先入其门，吴世璠自杀，马宝、胡国柱等降后被诛于京师，夏国相被执。", impact: "三藩之乱至此平定，清廷废藩下兵制，以绿营与驻防八旗分镇云贵，削平诸王所留的半独立军政格局；云南改设流官、兴屯政，铜矿与铸钱自此为国家币源之一。", figures: ["吴世璠","赵良栋","彰泰"], place: "昆明（今云南昆明）", state: "清", sources: ["《平定三逆方略》","《清史稿·赵良栋传》","《东华录》康熙朝"], tags: ["三藩","昆明"] }, related: ["cn--1673--p01"] },
  { id: "cn--1682--f01", track: "cn", year: 1682, yearApprox: false, dim: "figure", weight: 1, title: "顾炎武卒", summary: "乘马蹶仆，卒于曲沃，学者典型。", detail: { background: "顾炎武（1613—1682）自顺治末寓居陕西、山西，以二马二骡载书自随，所至考访金石、田赋、边塞，与关中士人李因笃、李颙讲学。", process: "1682年（康熙二十一年）正月，顾炎武在山西曲沃因乘马蹶地致病，月末卒，年七十；身后无子，以从子继，潘耒为其《日知录》作序而传其书。", impact: "其学以「博学于文、行己有耻」相表里，与黄宗羲、王夫之并称清初三大儒；《日知录》《天下郡国利病书》《音学五书》皆成清代学术的根基。", figures: ["顾炎武","潘耒"], place: "曲沃（今山西临汾曲沃）", state: "清", sources: ["《清史稿·儒林传》","张穆《顾亭林先生年谱》","《亭林文集》"], tags: ["顾炎武","考据"] }, related: ["cn--1670--c01"] },
  { id: "cn--1683--m01", track: "cn", year: 1683, yearApprox: false, dim: "military", weight: 4, title: "施琅取澎湖，郑氏降", summary: "旬日夺澎湖，水师压服台湾。", detail: { background: "1681年郑氏内部变乱，冯锡范杀郑克臧而立克塽；清廷以前两度攻台皆败，改用降郑之施琅专任水师，福建总督姚启圣协之。", process: "1683年（康熙二十二年）六月十四，施琅率舟师二百余自铜山进发，十六日与郑将刘国轩大战于澎湖，乘风连晓，越旦至暮破其船舰，旬日尽有诸岛；刘国轩北归，郑克塽遣使请降，八月施琅入鹿耳门受降。", impact: "延平政权亡，明末清初东南四十年的兵事结束；施琅以百口保郑氏不迁，郑氏宗族北徙入旗，汉人拓殖台湾自此无政治阻隔。", figures: ["施琅","郑克塽","刘国轩","姚启圣"], place: "澎湖—台湾（今澎湖—台南）", state: "清／明郑", sources: ["《清圣祖实录》卷一〇九","江日升《台湾外纪》","《（康熙）台湾府志》"], tags: ["澎湖","平台"] }, related: ["cn--1662--m01", "cn--1684--i01"] },
  { id: "cn--1684--e01", track: "cn", year: 1684, yearApprox: false, dim: "economy", weight: 4, title: "诏开海禁许民造船", summary: "四口设关前夜，东南渔业商船复业。", detail: { background: "迁海令行二十余年，界外田庐俱废、渔盐两失；平台之后户部侍郎议复界，福建巡抚慕天颜上《请开海禁疏》陈四利。", process: "1684年（康熙二十三年）九月诏开海禁，许民造船出洋贸易，于山东、江南、浙江、福建沿海设官汛守；出海船给以船票，记船户年貌籍贯与所货多寡，回洋稽查。", impact: "沿海田庐复业，商船重通日本、南洋与澳门，漳州月港、广州、宁波、上海由此复苏，形成1717年南洋之禁与1757年一口通商之前的海上贸易全盛期。", figures: ["玄烨","慕天颜"], place: "江南至广东沿海", state: "清", sources: ["《清圣祖实录》卷一一九","《粤海关志》","慕天颜《请开海禁疏》"], tags: ["开海禁","海商"] }, related: ["cn--1661--p02", "cn--1685--x01"] },
  { id: "cn--1684--i01", track: "cn", year: 1684, yearApprox: false, dim: "institution", weight: 3, title: "清设台湾府隶福建", summary: "一府三县，兵万人屯守。", detail: { background: "平台之后朝议有弃守之争，在廷诸臣有主迁其民而弃其地者；施琅上《恭陈台湾弃留疏》，言台湾为江浙闽粤四省之藩篱、土田物产之饶不可弃。", process: "1684年（康熙二十三年）四月，从施琅议设台湾府，隶福建布政司，领台湾、凤山、诸罗三县；驻总兵一员、副将三员、兵万人分防，设福建巡海道（台厦道）兼理厦门与台湾。", impact: "台湾自此入于清之版图，行保甲、科举、赋税之制，闽粤移民合法渡台，拓殖自南部向北推进；清廷旋颁渡台禁令与垦照之制，又成为百年后治台的症结。", figures: ["施琅","玄烨"], place: "台湾府（今台南）", state: "清", sources: ["《清圣祖实录》卷一一五","施琅《恭陈台湾弃留疏》","《（康熙）台湾府志》"], tags: ["台湾府","行政建制"] }, related: ["cn--1683--m01"] },
  { id: "cn--1685--m01", track: "cn", year: 1685, yearApprox: false, dim: "military", weight: 3, title: "第一次雅克萨之役", summary: "水陆并进，红衣炮摧其木城。", detail: { background: "俄国哥萨克自1640年代沿黑龙江东侵，1650年代据雅克萨、尼布楚，掳索伦、达斡尔诸部；清廷主力在南方与准部，两次遣使抗议无果，乃决用兵。", process: "1685年（康熙二十四年）六月，都统彭春、郎坦率水陆兵一万五千、战船二百余，携「神威将军」等红衣炮抵雅克萨城下，燔其外垣，晓谕劝降；俄将托尔布津毁城撤退，清军焚其木城而还。", impact: "这是清朝第一次以火炮与文书照会方式处理东北边界的军事行动；俄人旋复据雅克萨筑城，清乃有1686年再攻与1689年《尼布楚条约》。", figures: ["彭春","郎坦","玄烨","托尔布津"], place: "雅克萨（今黑龙江以北俄国阿尔加斯克）", state: "清／俄国", sources: ["《清圣祖实录》卷一二〇","《平定罗刹方略》","（俄）雅克萨档案文书"], tags: ["雅克萨","中俄"] }, related: ["cn--1686--m01", "cn--1689--p01"] },
  { id: "cn--1685--x01", track: "cn", year: 1685, yearApprox: false, dim: "explore", weight: 3, title: "四海关与唐船东渡", summary: "粤、闽、浙、江四关征税出海。", detail: { background: "开海之后须设关征舶税，户部与地方督抚议定通商口岸与则例。", process: "1685年（康熙二十四年）先后设粤海关（澳门、广州）、闽海关（厦门、漳州）、浙海关（宁波）、江海关（上海）四处，征船钞与货税；同年许商船领照出洋，唐船东渡长崎者骤增，以丝、糖、药、书易日本之铜、漆、硫磺。", impact: "四口通商格局成立，中国东南海商与日本、荷兰、暹罗的转口网络重接；日铜与南洋米糖内输，瓷与茶出口渐长，沿海商帮、会馆与市镇由此兴盛。", figures: ["慕天颜","玄烨"], place: "厦门—广州—宁波—上海", state: "清", sources: ["《粤海关志》卷三","《清朝文献通考·市籴考》","（日）《商舶载来书目》"], tags: ["海关","海上贸易"] }, related: ["cn--1684--e01"] },
  { id: "cn--1686--m01", track: "cn", year: 1686, yearApprox: false, dim: "military", weight: 3, title: "第二次雅克萨围城", summary: "长围亘冬，守军存者不足百人。", detail: { background: "托尔布津趁清军北撤复筑雅克萨城，驻俄兵八百余与火器；清廷以划界未成而俄人复进，命黑龙江将军萨布素再攻。", process: "1686年（康熙二十五年）七月，萨布素率军民八千余再围雅克萨，掘壕立炮、长围亘冬，城内冻馁疾疫，至年末存者不足百人；俄方遣使请撤围，愿委官议定边界。", impact: "此次围城成为中俄在相对平等条件下谈判的筹码，《尼布楚条约》以俄国在东段撤兵换得清撤围，是17至18世纪东亚最重要的一次划界。", figures: ["萨布素","托尔布津","玄烨"], place: "雅克萨（今黑龙江上游）", state: "清／俄国", sources: ["《清圣祖实录》卷一二六","《平定罗刹方略》","（俄）《戈洛文出使档案》"], tags: ["雅克萨","围城"] }, related: ["cn--1685--m01", "cn--1689--p01"] },
  { id: "cn--1688--a01", track: "cn", year: 1688, yearApprox: false, dim: "art", weight: 3, title: "《长生殿》成", summary: "洪昇三易稿，因演剧被除名。", detail: { background: "洪昇（1645—1704）钱塘人，师事毛先舒，受音律于徐麟，历十余年三易稿而成《长生殿》。", process: "1688年（康熙二十七年）《长生殿》传奇成，都四十出，写李隆基、杨玉环事，自谓「乐笑歌哀，皆本于性情」，借安史之乱写兴亡；翌年京师聚演，值孝懿皇后丧，给事中黄六鸿劾国恤张乐，洪昇与座客、优人得罪，除名者数十人。", impact: "与《桃花扇》并称清代传奇双峰，其曲词典雅、音律精严，至今为昆剧常演之剧；此案亦说明清初士人以戏文结社交游所带的政治风险。", figures: ["洪昇","黄六鸿"], place: "京师（今北京）", state: "清", sources: ["《长生殿》洪昇自序与凡例","《清史稿·文苑传》","（清）焦循《剧说》"], tags: ["传奇","昆剧"] }, related: ["cn--1699--a01"] },
  { id: "cn--1689--p01", track: "cn", year: 1689, yearApprox: false, dim: "politics", weight: 4, title: "尼布楚条约", summary: "中俄第一个边界条约，以外兴安岭为界。", detail: { background: "1686年雅克萨围城后俄方请和；俄国时与土尔扈特、哥萨克西路相持，清则噶尔丹东扰漠北，双方皆愿先定东界。", process: "1689年（康熙二十八年）七月至九月，索额图率使臣、护军与传教士徐日昇、张诚赴尼布楚，与俄使戈洛文议界，定约以满、汉、蒙、俄、拉丁五种文本互校：以额尔古纳河、格尔必齐河与外兴安岭为中俄东界，岭南之地属中国，岭北属俄国；雅克萨撤毁，俄人在华贸易照章纳税。", impact: "中俄之间第一个以条约与互译文本形式划定的边界，清由此得以抽调东北之兵北征噶尔丹；条约中「中国」与「大汗所属」的并置，是近代早期中国以主权语言对外订约的起点。", figures: ["索额图","戈洛文","徐日昇","张诚"], place: "尼布楚（今俄国涅尔琴斯克）", state: "清／俄国", sources: ["《清圣祖实录》卷一四三","《尼布楚条约》拉丁文本与满文本校释","（法）张诚《张诚日记》"], tags: ["尼布楚","划界"] }, related: ["cn--1685--m01", "cn--1686--m01", "world--1689--i01"] },
  { id: "cn--1690--i01", track: "cn", year: 1690, yearApprox: true, dim: "institution", weight: 3, title: "康熙朝《大清会典》成", summary: "清第一部行政法典，以衙门为纲。", detail: { background: "入关后典章多沿明旧而事例日积，官员职掌无所折衷，康熙二十三年诏修会典。", process: "自1684年开馆，至1690年前后（康熙二十九、三十年间）成《大清会典》（康熙朝），以宗人府、内阁、六部、都察院、理藩院等衙门为纲，各载职掌、机构与顺治、康熙间事例，为清代第一次官修行政法典。", impact: "有清一代五次修会典（康熙、雍正、乾隆、嘉庆、光绪）皆沿其体例，是研究清代官制、行政程序与边疆治理的第一手政书。", figures: ["玄烨"], place: "京师（今北京）", state: "清", sources: ["《大清会典》康熙朝刻本","《东华录》康熙朝","《清史稿·艺文志》"], tags: ["会典","政书"] }, related: ["cn--1647--i01"] },
  { id: "cn--1690--m01", track: "cn", year: 1690, yearApprox: false, dim: "military", weight: 3, title: "乌兰布通之战", summary: "火炮破驼城，噶尔丹北走。", detail: { background: "1688年噶尔丹击破喀尔喀土谢图汗，三部数十万口内徙长城，清廷受之；噶尔丹追袭内进，直抵乌兰布通，距北京七百余里。", process: "1690年（康熙二十九年）六月，圣祖以抚远大将军裕亲王福全、恭亲王常宁率军分路进讨，七月初三及乌兰布通，噶尔丹据峰、聚驼为城以拒；清军以火炮毁其驼城、奇兵绕出其右，噶尔丹乘夜北遁。", impact: "准部东进第一次被阻于京师屏外，清廷自此以全力西向；喀尔喀内属，为其后多伦会盟与盟旗制度所本。", figures: ["噶尔丹","福全","常宁","玄烨"], place: "乌兰布通（今内蒙古克什克腾旗）", state: "清／准噶尔", sources: ["《清圣祖实录》卷一四五","《平定朔漠方略》","张穆《蒙古游牧记》"], tags: ["乌兰布通","噶尔丹"] }, related: ["cn--1691--p01", "cn--1696--m01"] },
  { id: "cn--1691--p01", track: "cn", year: 1691, yearApprox: false, dim: "politics", weight: 4, title: "多伦会盟定喀尔喀", summary: "三十五旗编佐领，天子亲主会盟。", detail: { background: "乌兰布通战后，喀尔喀三部流亡内蒙，土谢图汗与札萨克图汗旧仇未解，理藩院主其会盟。", process: "1691年（康熙三十年）五月，圣祖亲幸多伦诺尔，与喀尔喀三部首领及内蒙古四十九旗会盟：断土谢图汗杀札萨克图汗之狱而释其仇，编其众为三十五旗，分左、右翼，设札萨克如内蒙古之例，封其首领为汗、亲王、郡王，并建汇宗寺以安之。", impact: "外蒙古自此内属，盟旗制度推行于漠北；理藩院与札萨克的管理体系成为清代治理蒙古、西藏、回部的骨架，也是近代中国北疆版图的由来之一。", figures: ["玄烨","察珲多尔济"], place: "多伦诺尔（今内蒙古锡林郭勒多伦）", state: "清", sources: ["《清圣祖实录》卷一五一","《理藩院则例》","张穆《蒙古游牧记》"], tags: ["多伦会盟","盟旗"] }, related: ["cn--1690--m01"] },
  { id: "cn--1692--c01", track: "cn", year: 1692, yearApprox: false, dim: "culture", weight: 3, title: "诏许天主教通行", summary: "礼部议准，教士与奉教者得保护。", detail: { background: "历狱之后地方禁止天主堂，江南、福建教案牵连及于奉教之民；耶稣会士以效力内廷、历局、炮局为请。", process: "1692年（康熙三十一年）三月，礼部议准：耶稣会士既已效力，天主教劝人为善、与中国礼俗不相妨碍，请如前明给匾保护之例，凡民入教不必禁止，诏可；于是各省天主堂多所重修。", impact: "天主教在华获得三十年的合法地位，据教会自记，至礼仪之争前中国教友约三十万人，士大夫奉教者众；此诏随1721年圣祖禁教与1724年世宗严禁而失效。", figures: ["玄烨","安多","闵明我"], place: "京师—江南—福建", state: "清", sources: ["《清圣祖实录》卷一五四","（法）费赖之《在华耶稣会士列传及书目》","《正教奉褒》"], tags: ["天主教","康熙"] }, related: ["cn--1664--c01"] },
  { id: "cn--1692--f01", track: "cn", year: 1692, yearApprox: false, dim: "figure", weight: 1, title: "王夫之卒", summary: "船山下学，六经责我开生面。", detail: { background: "王夫之（1619—1692）衡山人，1649年在衡山举兵拒清失败，赴肇庆行在又因党议几殆，归而隐居湘西石船山下，署「明遗人王夫之」。", process: "1692年（康熙三十一年）二月，王夫之卒于衡阳湘西草堂，年七十四；著《周易外传》《张子正蒙注》《读通鉴论》《宋论》《黄书》等百余种、八百余卷，多殁后由子王敔及后人刊刻，《四库》未收。", impact: "其气论与「理在气中」「日新之化」之说承张载而别程朱，史论以「趋时更新」释理势；晚清曾国藩刻《船山遗书》而大行，成为近代变革思想的重要资源。", figures: ["王夫之","王敔"], place: "衡阳（今湖南衡阳）", state: "清", sources: ["《清史稿·儒林传》","王敔《姜斋公行述》","《船山遗书》同治刻本"], tags: ["王夫之","气论"] }, related: [] },
  { id: "cn--1695--f01", track: "cn", year: 1695, yearApprox: false, dim: "figure", weight: 1, title: "黄宗羲卒", summary: "梨洲老人殁，史学与经世之学有传。", detail: { background: "黄宗羲（1610—1695）余姚人，号梨洲，尊其师刘宗周蕺山之学，主经史致用，讲学于证人书院。", process: "1695年（康熙三十四年）七月，黄宗羲卒于家，年八十六；著《明儒学案》《明夷待访录》《孟子师说》《南雷文案》，《宋元学案》未成而后为全祖望续补。", impact: "《明儒学案》为中国第一部系统的学术史，其以史证经、分源别派的路数开浙东史学一派，全祖望、章学诚、邵晋涵承之，直至近代。", figures: ["黄宗羲","全祖望"], place: "余姚（今浙江宁波余姚）", state: "清", sources: ["《清史稿·儒林传》","黄百家《梨洲先生神道碑文》","《宋元学案》"], tags: ["黄宗羲","学术史"] }, related: ["cn--1662--c01"] },
  { id: "cn--1696--m01", track: "cn", year: 1696, yearApprox: false, dim: "military", weight: 4, title: "昭莫多之役，噶尔丹败", summary: "西路由费扬古破其汗帐。", detail: { background: "1695年噶尔丹复聚众、借俄枪械与粮，1696年春东犯克鲁伦河；圣祖决计亲征，命东、中、西三路合围，自将中路。", process: "1696年（康熙三十五年）五月十三，抚远大将军费扬古率西路军至昭莫多（今蒙古国乌兰巴托东），以步军据岭、伏兵抄其背，自朝至未大战，斩首三千余级，生擒数百，获其孳畜、辎重与炮队；噶尔丹以十余骑遁。", impact: "准部汗国主力覆灭，噶尔丹于1697年走死，阿尔泰山以东至呼伦贝尔尽归于清；天山北路与伊犁则另启1755至1757年平定准部之局。", figures: ["费扬古","噶尔丹","玄烨"], place: "昭莫多（今蒙古国乌兰巴托东）", state: "清／准噶尔", sources: ["《清圣祖实录》卷一七二","《平定朔漠方略》","张穆《蒙古游牧记》"], tags: ["昭莫多","噶尔丹"] }, related: ["cn--1690--m01"] },
  { id: "cn--1699--a01", track: "cn", year: 1699, yearApprox: false, dim: "art", weight: 3, title: "《桃花扇》成", summary: "借离合之情，写兴亡之感。", detail: { background: "孔尚任（1648—1718）曲阜人，1684年圣祖驻跸曲阜时以衍圣公乐舞生授国子监博士，1686年随工部治水淮扬，访南明遗事于故老。", process: "1699年（康熙三十八年）《桃花扇》传奇成，都四十出，以侯方域、李香君之离合写南明弘光一朝兴亡，自题「借离合之情，写兴亡之感」；京师名公卿传观竞演，未几尚任以疑案免官。", impact: "与《长生殿》齐名，为清代历史剧的典范；其以曲笔存史之例，使传奇一体在清代承担史学与政治记忆之责，近代经欧阳予倩等改编为话剧、京剧。", figures: ["孔尚任","玄烨"], place: "京师（今北京）", state: "清", sources: ["《桃花扇》孔尚任本末与试一出","《清史稿·文苑传》","（清）焦循《剧说》"], tags: ["传奇","南明"] }, related: ["cn--1688--a01"] },
  { id: "cn--1703--a01", track: "cn", year: 1703, yearApprox: false, dim: "art", weight: 2, title: "热河行宫始建", summary: "塞外因山就水起行宫，后为避暑山庄。", detail: { background: "圣祖自1691年多伦会盟后北巡频仍，塞外驻跸需有水草与道路之便；1701年遣使相度热河温泉之地。", process: "1703年（康熙四十二年）始建热河行宫于温泉之侧，因山就水、不事雕镂，圣祖自题三十六景；雍正、乾隆两朝续扩，与外围之喇嘛庙群合为一体，至1792年全功告成，占地五百余万平方米。", impact: "热河由此成为清代的第二政治中心，康熙至咸丰数帝在此理政、接见蒙古、西藏、回部首领与俄国使臣，1793年英国马戛尔尼使团亦在此筵宴；其建筑兼采汉、藏、蒙式样，是清代多元治理在空间上的呈现。", figures: ["玄烨"], place: "热河（今河北承德）", state: "清", sources: ["《钦定热河志》","《清圣祖实录》卷二一二","《（嘉庆）大清一统志·承德府》"], tags: ["皇家园林", "建筑"] }, related: ["cn--1691--p01"] },
  { id: "cn--1705--a01", track: "cn", year: 1705, yearApprox: false, dim: "art", weight: 2, title: "八大山人朱耷卒", summary: "写意花鸟别开一格，鱼鸟多作白眼。", detail: { background: "朱耷（1626—1705）为明宁王权后裔，1645年国破后遁入僧道，五十岁后以书画谋生，号八大山人。", process: "1705年（康熙四十四年）朱耷卒于南昌，年八十；其画取法沈周、徐渭而大变，构图留白极多，鱼、鸟、石多作瞪目之态，署款「八大山人」连书似「哭之笑之」。", impact: "写意花鸟自此别开一格，清代中叶扬州八怪、近代的吴昌硕、齐白石、李苦禅皆承其法；其以书画寄遗民之痛，成为后世理解政治变局与艺术风格关系的典型个案。", figures: ["朱耷"], place: "南昌（今江西南昌）", state: "清", sources: ["《（同治）新建县志》","陈鼎《八大山人传》","《八大山人全集》（江西美术出版社）"], tags: ["绘画", "遗民"] }, related: [] },
  { id: "cn--1708--s01", track: "cn", year: 1708, yearApprox: false, dim: "science", weight: 3, title: "命测全国经纬地图", summary: "以西法三角测量，实测各省舆图。", detail: { background: "传统舆图无经纬、无实测，省府图志多袭旧说；《时宪历》与历象既用西法，遂议以实测改订天下地图。", process: "1708年（康熙四十七年）命传教士白晋、雷孝思、杜德美等与清臣同测，自京畿而东北、而黄河、长江诸省，用天文定点与三角连线，实测点达六百三十余处，各省分幅成图。", impact: "此为全国统一经纬度实测之始，测量中订正了海岸、河流与经纬差的旧误；其方法经耶稣会士通信报告回欧洲，成为18世纪欧洲东亚地理知识的直接来源。", figures: ["白晋", "雷孝思", "玄烨"], place: "京师及十三省", state: "清", sources: ["《清圣祖实录》卷二三一","（法）费赖之《在华耶稣会士列传及书目》","王庸《中国地理学史》"], tags: ["测绘", "西学"] }, related: ["cn--1717--s01"] },
  { id: "cn--1711--p01", track: "cn", year: 1711, yearApprox: false, dim: "politics", weight: 4, title: "戴名世《南山集》案", summary: "用南明年号，一案株及百人。", detail: { background: "桐城戴名世好搜明季遗事，其《南山集》引方孝标《滇黔纪闻》于永历、隆武之事直书年号，刊行于京师。", process: "1711年（康熙五十年）十月左都御史赵申乔劾其「语多狂悖」，名世下狱；1713年二月以大逆定罪处斩，年六十四，方孝标戮尸，族人与作序、刊刻、买卖者百余人流徙，方苞在狱中。", impact: "以史书年号正朔入罪，使清代士人于南明与建州之事讳不敢书；旋赦方苞出狱入武英殿修书，全祖望、邵晋涵以补辑遗闻为家学，浙东史学与文字狱由此纠缠一体。", figures: ["戴名世", "赵申乔", "方苞"], place: "京师—桐城（今安徽枞阳）", state: "清", sources: ["《清圣祖实录》卷二四七","戴名世《南山集》","故宫文献馆编《清代文字狱档》"], tags: ["文字狱", "清初士风"] }, related: ["cn--1663--p01", "cn--1726--p01"] },
  { id: "cn--1712--i01", track: "cn", year: 1712, yearApprox: false, dim: "institution", weight: 5, title: "盛世滋生人丁永不加赋", summary: "以现额丁银为定数，新增人丁不再加税。", detail: { background: "明末以来丁银随户口消长编审调整，民以生丁加赋为累，匿丁、逃亡者众，里甲赔累日深。", process: "1712年（康熙五十一年）诏以康熙五十年各省人丁钱粮总数为定额，「嗣后滋生人丁，永远不再加增钱粮」，另册题报，谓之盛世滋生人丁永不加赋；人头税自此与国家财政脱钩。", impact: "把人口增长与赋税增长分离，是传统户籍财政观的一次转折；它为雍正摊丁入亩直接铺路，也减轻了隐匿人口的动机，官方统计口数自1741年约1.43亿增至1794年约3.13亿，其制度前提在此。", figures: ["玄烨"], place: "天下各行省", state: "清", sources: ["《清圣祖实录》卷二四九","《（光绪）大清会典事例·户部》","何炳棣《中国人口研究（1368—1953）》"], tags: ["赋役", "人丁"] }, related: ["cn--1723--i02", "cn--1581--i01"] },
  { id: "cn--1712--x01", track: "cn", year: 1712, yearApprox: false, dim: "explore", weight: 3, title: "图理琛使土尔扈特", summary: "往返三载至伏尔加河，撰《异域录》。", detail: { background: "卫拉特蒙古土尔扈特部自1620年代西迁伏尔加河下游，与沙俄时生冲突；清廷欲知其虚实并示招徕之意。", process: "1712年（康熙五十一年）以内阁侍读图理琛为使，自京师经喀尔喀、色楞格斯克入俄境，历时三载，至阿斯特拉罕见阿玉奇汗于其帐；1715年归国，撰《异域录》记沿途山川、日程、俄之驻军与互市。", impact: "《异域录》是中国人第一部亲履俄国腹地写成的地理纪行，18世纪被译为俄、法、拉丁文，为欧洲了解西伯利亚东缘的重要文本；其记录亦成为清代北疆情报与恰克图交涉的基础。", figures: ["图理琛", "玄烨"], place: "京师至伏尔加河下游", state: "清", sources: ["图理琛《异域录》","《清圣祖实录》卷二四九","（法）杜赫德《中华帝国全志》所收译本"], tags: ["使行", "中俄"] }, related: ["cn--1727--p01", "cn--1691--p01"] },
  { id: "cn--1717--e01", track: "cn", year: 1717, yearApprox: false, dim: "economy", weight: 3, title: "南洋之禁与暹米内输", summary: "禁商船往南洋，旋许暹罗运米免税。", detail: { background: "开海后闽粤民人多出洋至吕宋、噶罗吧、占城贸易垦居，沿海米价日贵，朝议谓出洋者弃本业、载米而出为漏卮。", process: "1717年（康熙五十六年）议禁商船往南洋贸易，限期收回船照，惟赴日本、暹罗者不禁；翌年许暹罗米入广东、福建，免其船税货税，令督抚招商运米平粜。", impact: "南洋之禁未能切断闽粤海商，反使其转由巴达维亚、马尼拉的间接渠道营生，1727年（雍正五年）始准南洋之禁部分弛废；暹罗米内输则成清代广东平粜常例，米价、海运与人口压力自此进入财政议程。", figures: ["玄烨"], place: "广东—福建—南洋", state: "清", sources: ["《清圣祖实录》卷二七〇","《粤海关志》卷八","《（乾隆）大清会典事例·户部》"], tags: ["海禁", "米粮"] }, related: ["cn--1684--e01"] },
  { id: "cn--1717--s01", track: "cn", year: 1717, yearApprox: true, dim: "science", weight: 4, title: "《皇舆全览图》成", summary: "第一幅实测经纬度全国地图。", detail: { background: "自1708年起各省经纬实测，东北、关内、黄河、长江与西南诸省分幅测成；1711至1716年复遣人测西藏、哈密。", process: "约1717至1718年（康熙五十六年前后）《皇舆全览图》成，以经纬差定度、以三角法联测，分幅铜版印行，山岳、河道、府县以符号与色彩分层，另为满文、汉文两种文本。", impact: "这是中国第一幅以近代测绘方法完成的全国地图，其精度在19世纪末之前无出其右；副本经耶稣会士送回欧洲，1735年杜赫德据以刊图，此后百年间欧洲所绘中国地图多出其底本。", figures: ["雷孝思", "杜德美", "玄烨"], place: "京师（今北京）", state: "清", sources: ["《皇舆全览图》康熙内府刻本","（法）杜赫德《中华帝国全志》卷首地图","王庸《中国地理学史》"], tags: ["地图", "测绘"] }, related: ["cn--1708--s01"] },
  { id: "cn--1718--f01", track: "cn", year: 1718, yearApprox: false, dim: "figure", weight: 1, title: "孔尚任卒", summary: "《桃花扇》作者终于曲阜。", detail: { background: "孔尚任以1699年《桃花扇》成而名动京师，未几以疑案免官，1700年南归，晚岁居曲阜。", process: "1718年（康熙五十七年）孔尚任卒于曲阜，年七十一；另有《湖海集》《岸堂文集》行世，《桃花扇》稿本在家塾与戏班间续有传习。", impact: "其生平与《桃花扇》之命运，成为清初文人在政治记忆与皇权审查之间处境的典型样本；孔氏家班此后仍于曲阜搬演此剧，至乾隆间刊本通行。", figures: ["孔尚任"], place: "曲阜（今山东济宁曲阜）", state: "清", sources: ["《清史稿·文苑传》","孔尚任《桃花扇·本末》","（清）蒋士铨《临川梦》所附考证"], tags: ["戏曲", "孔尚任"] }, related: ["cn--1699--a01"] },
  { id: "cn--1721--c01", track: "cn", year: 1721, yearApprox: true, dim: "culture", weight: 4, title: "礼部议禁天主教", summary: "礼仪之争决裂，各省天主堂封禁。", detail: { background: "1704年多罗来华禁中国教友祀孔祭祖，1715年教宗通谕重申其禁；圣祖初犹两可，命遣使问西洋，终无以应。", process: "1720年末至1721年初（康熙五十九年、六十年间）礼部议准：西洋人遵其教主之命，与中国礼俗不合，禁止各省传教；在院效力者留京师，余遣回澳门，民人入教者治以应得之罪。", impact: "礼仪之争使天主教在华失去合法地位，西学输入自历法、火器、测绘退缩于宫廷一隅，各省教堂或充公或改社学；此禁历雍正、乾隆、嘉庆三朝，至1840年后由条约体制推翻。", figures: ["玄烨", "嘉乐"], place: "京师及各行省", state: "清", sources: ["《清圣祖实录》卷二九一","故宫文献馆编《康熙与罗马使节关系文书》","（法）费赖之《在华耶稣会士列传及书目》"], tags: ["礼仪之争", "禁教"] }, related: ["cn--1692--c01"] },
  { id: "cn--1722--p01", track: "cn", year: 1722, yearApprox: false, dim: "politics", weight: 4, title: "圣祖崩，世宗立", summary: "畅春园宣遗命，皇四子入承大统。", detail: { background: "圣祖两度废立皇太子，诸皇子各树其党，步军统领隆科多提督九门、川陕总督年羹尧握西路兵权。", process: "1722年（康熙六十一年）十一月十三日圣祖崩于畅春园，隆科多宣读遗命，皇四子允禛即位，改元雍正；允禩、允禟等受封而失其援，年羹尧以川陕之师为外援。", impact: "世宗以非常之局入承，其即位之正至今为史家聚讼；此后其追比亏空、整饬吏治、立秘密建储、设军机房，皆可视为对合法性焦虑的制度化回应，清代皇权由此进一步集中。", figures: ["玄烨", "胤禛", "隆科多", "年羹尧"], place: "畅春园—京师（今北京）", state: "清", sources: ["《清圣祖实录》卷末","《清世宗实录》卷一","杨启樵《雍正帝及其密折制度研究》"], tags: ["储位", "雍正"] }, related: ["cn--1723--i01"] },
  { id: "cn--1723--i01", track: "cn", year: 1723, yearApprox: false, dim: "institution", weight: 3, title: "创秘密建储之法", summary: "书名藏匣，悬于正大光明匾后。", detail: { background: "两度废太子与诸皇子夺嫡之祸，世宗身预其中，以嫡长预定之制适足长争端。", process: "1723年（雍正元年）七月召诸王大臣于乾清宫，亲书皇太子名于锦匣，密封置于「正大光明」匾后，另录一纸藏于内侍；不建东宫，不宣其名为谁。", impact: "秘密建储终清之世行之不改，高宗、仁宗、宣宗、文宗皆由此定，此后清代不再出现公开的储位之争与东宫集团；代价是继承权完全委于皇帝一人的私意与临终之局。", figures: ["胤禛"], place: "乾清宫（今北京）", state: "清", sources: ["《清世宗实录》卷九","昭梿《啸亭杂录》","《（光绪）大清会典事例·宫室》"], tags: ["建储", "皇位继承"] }, related: ["cn--1722--p01", "cn--1735--p01"] },
  { id: "cn--1723--i02", track: "cn", year: 1723, yearApprox: false, dim: "institution", weight: 5, title: "摊丁入亩", summary: "并丁银于田赋，无田者不纳丁。", detail: { background: "1712年丁银定额后，无地之贫丁仍供催科，里甲摊派赔累；直隶巡抚李维钧请通省丁银摊入地粮。", process: "1723年（雍正元年）自直隶始行摊丁入亩，以一州县之丁银均摊于该州县之地粮，每亩征银若干，随后二年、三年渐行于山东、浙江、江西、湖广诸省，至1729年前后通行天下（盛京、台湾庄赋另有其制）。", impact: "人头税并入财产税，赋役由「税人身」转为「税土地」，户籍编审与征税脱钩，隐匿人口大减；佃户、行商、矿工不再受丁银之累，亦为清代中叶以后向边地、山区的大规模移民提供了制度出口。", figures: ["胤禛", "李维钧", "田文镜"], place: "直隶及各省", state: "清", sources: ["《（雍正）东华录》","《清史稿·食货志》","《（光绪）大清会典事例·户部》"], tags: ["摊丁入亩", "赋役"] }, related: ["cn--1712--i01", "cn--1581--i01"] },
  { id: "cn--1723--i03", track: "cn", year: 1723, yearApprox: false, dim: "institution", weight: 3, title: "奏折制度通行天下", summary: "折由内廷径进，题本阁票徒为故事。", detail: { background: "密折始于康熙朝赐第近臣之专折奏事；世宗以夺嫡之局深知章奏经内阁、通政司之弊。", process: "1723年起，督抚、藩臬、提镇及钦差多得具折奏事，折由奏事处径进内廷，皇帝亲加朱批后发回，事不先关白阁臣；题本、奏本之制虽存，钱粮刑名之外的政务多取决于折，批语动辄数百字。", impact: "奏折使皇帝绕开内阁与议政机构而直控地方信息与人事，行政效率与君主独断同时增长，清代中枢的运作自此以折、批为轴心，军机处即由此渠道而生。", figures: ["胤禛"], place: "京师及各行省", state: "清", sources: ["《（雍正）朱批谕旨》","中国第一历史档案馆编《雍正朝汉文朱批奏折汇编》","杨启樵《雍正帝及其密折制度研究》"], tags: ["奏折", "中枢制度"] }, related: ["cn--1732--i01"] },
  { id: "cn--1724--i01", track: "cn", year: 1724, yearApprox: false, dim: "institution", weight: 4, title: "耗羡归公与养廉银", summary: "火耗提为公项，官吏给养廉银。", detail: { background: "州县征钱粮例加火耗以补熔铸之亏与自润，加派至数成者有之，民怨而上级衙门之费亦取给于此。", process: "1724年（雍正二年）从山西布政使高成龄之请，令耗羡悉归公，充地方公费与官吏俸给，名养廉银；总督岁给二万两，州县自四百两至二千两视缺分等差，同时严禁私派。", impact: "把非法加派转为公开定额，是清代地方财政最有力的一次整顿，亏空与苛派一时敛迹；但养廉银随物价与摊捐而失效，道光以后火耗、捐输复起，其效仅及百年。", figures: ["胤禛", "高成龄"], place: "山西及各行省", state: "清", sources: ["《（雍正）东华录》","《清朝文献通考·国用考》","陈锋《清代军费研究》"], tags: ["耗羡", "财政"] }, related: ["cn--1723--i03"] },
  { id: "cn--1725--i01", track: "cn", year: 1725, yearApprox: false, dim: "institution", weight: 4, title: "改土归流行于西南", summary: "废土司设流官，黔滇桂一体推行。", detail: { background: "西南土司世有其地，自立赋役、互相攻灭，土民之生命财产系于头人；明人已议改流而未果。", process: "1725年（雍正三年）以鄂尔泰为云贵广西总督主其事，自云南乌蒙、镇雄、东川先行，兵威与招抚并用，废其土官，设流官、编保甲、清田亩、定赋额；1726至1736年间推及贵州古州、广西泗城、广西镇安与四川边地，删土司数百，新增府厅州县数十。", impact: "改土归流把西南边地纳入直接的州县赋役与司法体系，汉人客民、垦殖、矿冶随官道而入，土司社会解体；新定赋额、汉苗田土之争与流官贪苛，也激起1735年黔东南苗民起事。", figures: ["鄂尔泰", "胤禛"], place: "云南—贵州—广西", state: "清", sources: ["《清史稿·鄂尔泰传》","《（雍正）朱批谕旨》","《（嘉庆）广西通志·土司》"], tags: ["改土归流", "西南"] }, related: ["cn--1735--m01"] },
  { id: "cn--1726--p01", track: "cn", year: 1726, yearApprox: false, dim: "politics", weight: 3, title: "查嗣庭乡试案", summary: "以试题字面获罪，停浙江乡试五年。", detail: { background: "世宗即位后屡申饬科道朋党，浙江士人在朝者众，乡试试题为察官所注目。", process: "1726年（雍正四年）江西乡试正考官查嗣庭以试题「维民所止」等语被指暗斥「康熙」二字去其首，又以其日记讥切时政入告；下狱论大逆，1727年死于狱，戮尸，子侄流戍，浙江省文武乡试停五科，1735年高宗即位乃复。", impact: "文字狱的入罪之途由史书年号移向经义题句与私人日记，罗织更无定准；停一省乡试数科，是把士人的集体责任写入刑案，禁毁与删改自此成为清代书籍史的背景条件。", figures: ["胤禛", "查嗣庭"], place: "京师—南昌—海宁", state: "清", sources: ["故宫文献馆编《清代文字狱档》","《（雍正）东华录》","（清）福格《听雨丛谈》"], tags: ["文字狱", "科举"] }, related: ["cn--1711--p01", "cn--1728--p01"] },
  { id: "cn--1727--p01", track: "cn", year: 1727, yearApprox: false, dim: "politics", weight: 4, title: "恰克图条约定北界", summary: "中俄划中段边界，定恰克图互市。", detail: { background: "《尼布楚条约》仅定东北一段，喀尔喀北界未画；俄人越境建堡、收贡赋，清廷以定界与互市为交涉要目。", process: "1727年（雍正五年）中俄使臣萨瓦与清臣策棱等议定于色楞格斯克附近立《布连斯奇条约》，自沙毕纳伊岭至额尔古纳河一线画界，以南属中国、以北属俄国；次年三月于恰克图换约并增商业条款，准俄商每三年一次赴京贸易，于恰克图、尼布楚设市纳税。", impact: "中俄中段与北段边界由此划定，俄国南进在百余年中被限于界线之外；恰克图成为茶叶、布匹与皮毛、白银交换的口岸，晋商由此兴起，张家口至恰克图的商路是近代以前东亚最长的国际贸易线之一。", figures: ["胤禛", "萨瓦", "策棱"], place: "恰克图—色楞格斯克（今蒙俄边境）", state: "清／俄国", sources: ["《（雍正）东华录》","《理藩院则例》","张穆《蒙古游牧记》"], tags: ["恰克图", "划界"] }, related: ["cn--1689--p01", "cn--1712--x01"] },
  { id: "cn--1728--a01", track: "cn", year: 1728, yearApprox: false, dim: "art", weight: 3, title: "唐英督景德镇御窑", summary: "驻厂协造，亲习泥土釉料火候。", detail: { background: "江西御窑自康熙十九年重建，器多粗拙不合用；内务府郎中唐英奉命往厂协造窑务。", process: "1728年（雍正六年）唐英驻景德镇御窑厂，与窑户、工匠同作息，于埏埴、釉料、火候、画样皆身亲其试，仿古宋、元、明诸窑而兼采西洋珐琅彩之制；先后督窑逾二十年，历雍正、乾隆两朝。", impact: "其时御窑胎薄釉匀、彩绘精工为一代之最，仿朱砂、郎窑、汝官诸釉皆成；唐英《陶成纪事碑》逐列釉名与配方，与《陶冶图说》同为研究清代瓷业技术与分工的第一手文献。", figures: ["唐英", "胤禛"], place: "景德镇（今江西景德镇）", state: "清", sources: ["唐英《陶成纪事碑》","《（嘉庆）饶州府志·窑司》","《（乾隆）江西通志》"], tags: ["瓷器", "御窑"] }, related: [] },
  { id: "cn--1728--p01", track: "cn", year: 1728, yearApprox: false, dim: "politics", weight: 4, title: "曾静案与《大义觉迷录》", summary: "劝岳钟琪反清，供出吕留良华夷之辨。", detail: { background: "湖南书生曾静、张熙以吕留良（1629—1683）文集之华夷之辨为据，遣张熙投书川陕总督岳钟琪，劝其背清。", process: "1728年（雍正六年）岳钟琪以其事上闻，曾静等被捕；狱辞牵及吕留良著述，1729年定谳，吕留良已死，剖棺戮尸，子孙门人戍边，藏书尽毁；世宗独赦曾静、张熙，亲撰《大义觉迷录》，历辩华夷内外之说，颁直省学宫令生员讲读。", impact: "此为文字狱中唯一由皇帝亲自下场辩论义理者，然高宗即位后旋诛曾静、张熙并严禁《大义觉迷录》，自毁其父之论；以「华夷」立说者必以大逆论，自此成为清代之定例，士论益趋于考据。", figures: ["胤禛", "曾静", "岳钟琪", "吕留良"], place: "湖南—京师（今北京）", state: "清", sources: ["《（雍正）东华录》","《大义觉迷录》","故宫文献馆编《清代文字狱档》"], tags: ["文字狱", "华夷之辨"] }, related: ["cn--1726--p01"] },
  { id: "cn--1732--i01", track: "cn", year: 1732, yearApprox: false, dim: "institution", weight: 5, title: "设军机处", summary: "自军机房改设，中枢之权尽归内廷。", detail: { background: "1729年用兵准噶尔，西北军报旁午，内阁在外、程式迟缓，机要文移不敷时会。", process: "1730年（雍正八年）于隆宗门内设军机房，选内阁谨密大臣入直缮拟；1732年（雍正十年）改称军机处，以大学士、尚书、侍郎为军机大臣，下设军机章京，跪受笔录、承旨寄信，督抚奉「字寄」行事，议政王大臣会议渐成闲名。", impact: "军机处取代会典所载之外朝机构，成为清代实际的中枢，其「简、速、密」三长使兵事、河工、赈灾皆可一日取决；此制沿至1911年责任内阁成立乃废，凡一百七十九年，是理解清代皇权极盛的关键。", figures: ["胤禛", "张廷玉", "鄂尔泰"], place: "京师隆宗门内（今北京）", state: "清", sources: ["《（雍正）东华录》","《（光绪）大清会典事例·军机处》","《清史稿·职官志》"], tags: ["军机处", "中枢制度"] }, related: ["cn--1723--i03"] },
  { id: "cn--1735--m01", track: "cn", year: 1735, yearApprox: false, dim: "military", weight: 3, title: "古州苗民起事", summary: "黔东南反清丈加赋，数月众至二十万。", detail: { background: "改土归流后于黔东南设古州、清江、丹江等厅，丈量田亩、编保甲、置汛塘，熟苗土目与流官争讼日起。", process: "1735年（雍正十三年）春，古州、八寨、台拱苗民以清丈加赋起事，数月之间响应者数十万，攻围厅县城寨；清以张广泗统湖广、四川、贵州之兵分路进剿，焚毁碉寨，高宗即位后改主招抚，1736年事定。", impact: "用兵经年，耗帑银以数百万计；清廷于其地设新疆六厅、屯军置堡，苗汉田土与诉讼自此纠缠，至1795年石柳邓、吴八月之起事与1855年之变，皆循此结构重演。", figures: ["张广泗", "胤禛"], place: "古州—清江（今贵州黔东南）", state: "清", sources: ["《清史稿·张广泗传》","《（乾隆）贵州通志》","《（雍正）东华录》"], tags: ["苗疆", "改土归流"] }, related: ["cn--1725--i01"] },
  { id: "cn--1735--p01", track: "cn", year: 1735, yearApprox: false, dim: "politics", weight: 4, title: "高宗即位改元乾隆", summary: "宽严相济为政，旋诛曾静禁其书。", detail: { background: "世宗以秘密建储书第四子弘历名藏于乾清宫，弘历时年二十五，受业于福敏、蔡世远、朱兰泰等。", process: "1735年（雍正十三年）八月世宗崩于圆明园，九月弘历即位，改明年为乾隆；释允禵等幽禁之亲王，罢世宗朝开矿、营造诸急政，旋以「惑众」诛曾静、张熙，禁《大义觉迷录》，追斥科名阿苟之士。", impact: "高宗在位六十年（1735—1796）而又训政四年，为清代疆域、人口与财赋之极盛，亦为文字狱与书籍禁毁最多、吏治由整饬转入奢靡之际；其朝之得失多系于一人之好尚。", figures: ["弘历", "胤禛", "鄂尔泰", "张廷玉"], place: "京师（今北京）", state: "清", sources: ["《清世宗实录》卷末","《清高宗实录》卷一","《（乾隆）东华录》"], tags: ["乾隆", "即位"] }, related: ["cn--1723--i01", "cn--1728--p01"] },
  { id: "cn--1736--p01", track: "cn", year: 1736, yearApprox: false, dim: "politics", weight: 2, title: "与准噶尔议和", summary: "西北兵疲而讲和，阿尔泰山为界。", detail: { background: "1731年和通泊之败使清军在西北转入守势，北路军台粮运岁费巨万，户部请罢大举。", process: "1736年（乾隆元年）高宗以准部亦困于兵，遣使议和；1739年定界，以阿尔泰山与额尔齐斯河上游为限，准噶尔守伊犁，喀尔喀守山南，划游牧之界，互市于扎克拜达里克。", impact: "此和约使清廷获得近二十年的休整，沿边屯田、马厂与军台得以充实，火器与粮储积至1750年代；一旦1745年后准部内乱，清即得以趁虚西进，其条件实成于此。", figures: ["弘历", "噶尔丹策零"], place: "伊犁—阿尔泰山", state: "清／准噶尔", sources: ["《平定准噶尔方略》前编","《（乾隆）东华录》","《清史稿·准噶尔传》"], tags: ["准噶尔", "和议"] }, related: ["cn--1755--m01"] },
  { id: "cn--1739--c01", track: "cn", year: 1739, yearApprox: false, dim: "culture", weight: 4, title: "《明史》成书刊行", summary: "历百年而后定，二十四史之殿。", detail: { background: "顺治二年开明史馆，康熙十八年以博学鸿词征士分撰，万斯同以布衣总其稿，王鸿绪整理于后。", process: "1739年（乾隆四年）《明史》三百三十二卷成于武英殿，张廷玉等为总裁，本纪、志、表、列传齐备；于明代阁臣、七臣、阉党、土司各立专传，而南明福、唐、鲁、桂诸王事迹削而不载。", impact: "为二十四史中最后成书的一部，体例谨严、文字洁净为后世所称；惟于建州女直与明末辽事多所回护，孟森《明元清系通纪》即专攻其讳，清人论明亡之得失乃转入私修之史。", figures: ["张廷玉", "万斯同", "弘历"], place: "武英殿（今北京）", state: "清", sources: ["《明史》武英殿刻本","王鸿绪《明史稿》","孟森《明元清系通纪》"], tags: ["官修史", "明史"] }, related: ["cn--1711--p01"] },
  { id: "cn--1739--d01", track: "cn", year: 1739, yearApprox: false, dim: "disaster", weight: 3, title: "宁夏平罗大地震", summary: "冬夜地震约八级，二城为墟。", detail: { background: "银川—河套地堑为华北西北的主要发震带，宁夏府城、平罗县城多夯筑垣墙，民居半为土洞。", process: "1739年1月3日（乾隆三年十二月三日）夜，宁夏府城与平罗一带地大震，《中国历史强震目录》定其震级约8.0级；城郭衙署庙宇墩台尽圮，地裂涌水黑泥，黄河岸崩二十余里，官书与府志所报死者自二万余人至数万不等，现代学者据乾隆初宁夏户口与驻军数额推定实际当在二万人上下。", impact: "清廷发帑振济、蠲免宁夏属钱粮，拨银重筑城垣与满城；其断崖、地震湖遗迹今存贺兰山东麓，为西北地震危险性评定与银川盆地活动构造研究的核心历史依据。", figures: ["弘历"], place: "宁夏—平罗（今宁夏银川—平罗）", state: "清", sources: ["《（乾隆）宁夏府志》","国家地震局《中国历史强震目录》","《清高宗实录》卷八二"], tags: ["地震", "宁夏"] }, related: [] },
  { id: "cn--1742--s01", track: "cn", year: 1742, yearApprox: false, dim: "science", weight: 3, title: "《医宗金鉴》成", summary: "太医院奉敕纂九十种之医书。", detail: { background: "历代方书繁杂、异说竞出，太医院请以御院所藏与通行诸书删繁撮要，纂为定本。", process: "1739年诏修，至1742年（乾隆七年）《医宗金鉴》九十卷成，太医院判吴谦与刘裕铎为总纂；上自《伤寒》《金匮》下及内科、妇科、幼科、针灸、正骨、外科诸门，图说并载，御赐书名，颁行天下学宫为医学课读之本。", impact: "其《正骨心法要旨》汇录军中与民间的整复手法、固定器具与止血麻药之法，为中医骨伤科的集成交卷；书经使节与商船传入日本、朝鲜、越南，是清代流传最广的官修医书。", figures: ["吴谦", "刘裕铎", "弘历"], place: "京师（今北京）", state: "清", sources: ["《医宗金鉴》乾隆内府刻本","《四库全书总目·医家类》","《清史稿·艺术传》"], tags: ["医学", "官修书"] }, related: [] },
  { id: "cn--1743--d01", track: "cn", year: 1743, yearApprox: false, dim: "disaster", weight: 3, title: "直隶山东大水成饥", summary: "两年连涝，京师米贵，振帑数百万。", detail: { background: "乾隆初年华北夏雨偏多，永定河、运河、黄河下游屡决，京南至山东一路积水；顺天、河间诸属地势低洼。", process: "1742至1743年（乾隆七、八年）夏秋大雨浃旬，直隶顺天、保定、河间、沧州与山东济宁、东昌一带并遭大水，田庐漂没、漕运阻滞，灾及数十州县；《清史稿·灾异志》与地方志所报饥殍、流移之数相踵，户部先后拨帑、截漕、平粜，以工代振。", impact: "此为18世纪华北一次有明确气候背景的大灾荒，现代气候学者以树轮、方志与档案复原其雨带偏南之局，视为清代前期人口压力与救济能力的一次压力试验；高宗朝河工、海塘、常平仓三大政，由此成为常年国用之大纲。", figures: ["弘历"], place: "直隶—山东", state: "清", sources: ["《清高宗实录》","《清史稿·灾异志》","曹树基《中国人口史》第五卷"], tags: ["水灾", "振济"] }, related: ["cn--1679--d01"] },
  { id: "cn--1747--m01", track: "cn", year: 1747, yearApprox: false, dim: "military", weight: 3, title: "第一次大金川之役", summary: "石碉依山，清军顿兵两年而议抚。", detail: { background: "大金川土司莎罗奔据今四川金川、丹巴之险，连筑石碉，兼并周邻土司、攻掠革布什咱、巴底诸地。", process: "1747年（乾隆十二年）十二月命四川总督张广泗进剿，继以大学士讷亲经略、傅恒代将其军，兵号三万，抵美诺、刮木坝；碉楼依山起、炮石互御，清军仰攻辄挫，将帅死者相属，两广、云南之兵续调。", impact: "1749年（乾隆十四年）以莎罗奔奉表噶拉布而罢兵，耗帑银以千万计；石碉之险使清廷认识到土司之兵不可以平原阵法制之，乃专练健锐营、云梯与火炮，此备于1776年第二次金川之役收效。", figures: ["莎罗奔", "张广泗", "讷亲", "傅恒"], place: "大金川（今四川阿坝金川）", state: "清", sources: ["《清史稿·四川土司传》","魏源《圣武记》卷七","《（乾隆）东华录》"], tags: ["金川", "土司"] }, related: ["cn--1755--m01"] },
  { id: "cn--1749--f01", track: "cn", year: 1749, yearApprox: false, dim: "figure", weight: 1, title: "方苞卒", summary: "望溪老人殁，桐城古文有传。", detail: { background: "方苞（1668—1749）桐城人，以古文名于时，1713年因《南山集》案牵连下狱，出而入武英殿修书。", process: "1749年（乾隆十四年）方苞卒，年八十二；其论文标「义法」，谓「言有物」、「言有序」，所为《狱中杂记》写刑部牢狱之状最为世传，有《望溪全集》行世。", impact: "其说历刘大櫆、姚鼐而成为桐城派，乾隆、嘉庆间有「天下文章其在桐城」之目，与汉学考据并立为清代文学与学术的两大源流，其影响延至曾国藩与清末的京师文人群体。", figures: ["方苞", "刘大櫆"], place: "京师—桐城（今安徽枞阳）", state: "清", sources: ["《清史稿·文苑传》","方苞《望溪全集》","刘大櫆《论文偶记》"], tags: ["桐城派", "古文"] }, related: ["cn--1711--p01"] },
  { id: "cn--1750--e01", track: "cn", year: 1750, yearApprox: true, dim: "economy", weight: 4, title: "玉米番薯遍垦山区", summary: "旱地高产作物入南山，棚民满山谷。", detail: { background: "玉米自明代由海路与西路入华，番薯自1590年代由闽人自吕宋携归；雍乾之际平原田土不足养增口，官府屡劝垦荒。", process: "约1740至1760年间，四川、湖广、陕西、云南、贵州之秦巴山地与棚民垦区广种玉米、番薯、马铃薯，不择地势、不费粪壅，亩收数倍于五谷；1735、1746、1754年屡诏督抚劝种番薯，给种立社。", impact: "旱地高产作物使山地的载人口量骤增，清代统计人口自1741年约1.43亿增至1794年约3.13亿，其物质基础在此；但垦山伐林引起山洪、石田与河道淤塞，乾嘉以后秦蜀、鄂西北的河患与白莲教起事，均与这一移民—垦殖结构有关。", figures: ["弘历"], place: "川楚陕滇黔山区", state: "清", sources: ["《（乾隆）户部奏销册》所载垦额","《清高宗实录》劝种番薯诸诏","曹树基《中国人口史》第五卷"], tags: ["作物", "垦殖"] }, related: ["cn--1610--c01", "cn--1796--m01"] },
  { id: "cn--1751--i01", track: "cn", year: 1751, yearApprox: false, dim: "institution", weight: 4, title: "西藏善后章程十五条款", summary: "废郡王独治，驻藏大臣与达赖共理。", detail: { background: "1728年设驻藏大臣于拉萨，而藏政实出郡王；1750年（乾隆十五年）珠尔默特那木扎勒袭杀驻藏大臣傅清等，拉萨大乱，清将策楞率军入藏。", process: "1751年（乾隆十六年）颁《西藏善后章程》十五条：废郡王独治之制，设噶厦，置噶布伦四员理藏务，凡官员补放、边防汛地、户口赋税皆须会同驻藏大臣；将达赖喇嘛之辖地与属民归其统辖，拨额兵驻前后藏，粮台设打箭炉、拉里。", impact: "驻藏大臣自此由监察变为与达赖同主藏政，噶厦之制沿至1959年；此后1788、1791年廓尔喀两次入寇，清廷以《藏内善后章程》二十九条与金瓶掣签完成其制度，构成中央治藏的基本框架。", figures: ["弘历", "傅清", "策楞"], place: "拉萨（今西藏拉萨）", state: "清", sources: ["《清高宗实录》卷三九一","《卫藏通志》","《理藩院则例》"], tags: ["驻藏大臣", "噶厦"] }, related: ["cn--1757--m01"] },
  { id: "cn--1751--p01", track: "cn", year: 1751, yearApprox: false, dim: "politics", weight: 2, title: "高宗首次南巡", summary: "阅河海之防，收江南士民之心。", detail: { background: "圣祖六巡江南，世宗在位十三年不巡；高宗即位后以河工、海塘与察吏观民为请，群臣屡疏乃允。", process: "1751年（乾隆十六年）正月至五月首次南巡，幸泰山、孔庙，阅黄河、洪泽湖诸堤与浙江海宁鱼鳞石塘，至江宁、苏州、杭州，所至蠲驿费、免积欠、加江浙两省学额，召对旧儒、祭明陵；迎銮供顿之费多出盐商捐输。", impact: "六次南巡（1751—1784）以巡视河海之防与笼络江南士商为实，其规模与费用在乾隆中叶后成为地方财政重负；嘉庆朝亲政即以「南巡之费、河工之费、军需之费」并称三大政病。", figures: ["弘历"], place: "江宁—苏州—杭州", state: "清", sources: ["《清高宗实录》","《钦定南巡盛典》","昭梿《啸亭杂录》"], tags: ["南巡", "江南"] }, related: ["cn--1757--e01"] },
  { id: "cn--1755--m01", track: "cn", year: 1755, yearApprox: false, dim: "military", weight: 5, title: "清军取伊犁，平准噶尔", summary: "两路西进收天山北路，六十五年之患一役。", detail: { background: "1745年噶尔丹策零死后准部内乱，达瓦齐与阿睦尔撒纳相攻；1754年阿睦尔撒纳率辉特、杜尔伯特诸部内属，具言伊犁虚实。", process: "1755年（乾隆二十年）春分南北两路进兵，班第等率满、蒙、索伦兵三万余直入伊犁，取惠远旧城，释被羁之众，达瓦齐遁至格登山，为厄鲁特臣子所擒送京师；清廷留兵于伊犁、塔尔巴哈台，册封诸部台吉。", impact: "自1690年乌兰布通以来六十五年的准部之患至此告一段落，天山北路入于清；然是年秋阿睦尔撒纳以不得长卫拉特再叛，北路尽失，历1757年乃定，天山南路亦因之而有平定回部之役。", figures: ["弘历", "班第", "达瓦齐", "阿睦尔撒纳"], place: "伊犁（今新疆伊宁）", state: "清／准噶尔", sources: ["《平定准噶尔方略》正编","《清史稿·准噶尔传》","魏源《圣武记》卷二"], tags: ["准噶尔", "伊犁"] }, related: ["cn--1736--p01", "cn--1757--m01"] },
  { id: "cn--1755--p01", track: "cn", year: 1755, yearApprox: false, dim: "politics", weight: 3, title: "胡中藻《坚磨生诗钞》案", summary: "诗句「论浊清」获罪，兼斥座师。", detail: { background: "胡中藻为讷亲、鄂尔泰门生，以诗名于乾隆初；鄂、张两相之党议至是未息。", process: "1755年（乾隆二十年）胡中藻所著《坚磨生诗钞》被指「一把心肠论浊清」等语悖逆，下刑部议斩，1756年伏诛；鄂尔泰虽已死，追削其贤良方祀，大学士张廷玉亦得罪，讷亲子孙夺官。", impact: "以一字一句罗织而兼及朝堂朋党，是文字狱与政治整肃合流的典型；乾隆朝文字狱之数倍于雍正朝、禁毁书籍之广为历朝所未有，士人由此于诗文相戒不敢涉时务。", figures: ["弘历", "胡中藻", "鄂尔泰"], place: "京师（今北京）", state: "清", sources: ["《（乾隆）东华录》","《坚磨生诗钞》","故宫文献馆编《清代文字狱档》"], tags: ["文字狱", "朋党"] }, related: ["cn--1728--p01"] },
  { id: "cn--1757--e01", track: "cn", year: 1757, yearApprox: false, dim: "economy", weight: 5, title: "广州一口通商", summary: "欧船止泊粤海关，浙闽江浙之埠闭。", detail: { background: "开海后欧船屡至宁波采买湖丝、茶叶，浙抚以洋船日聚、丝茶外流为忧；户部以海防与风俗为请。", process: "1757年（乾隆二十二年）谕嗣后外洋红毛等国商船止许在粤海关收泊交易，不得更赴浙、闽、江南海关，浙海关税则亦加倍以绝其来路（日本、西洋之外的东洋南洋贸易仍四口并行）；1760年前后粤省行商议定公行规条，洋船须由保商、通事承充，夷商不得私与官民交接、不得携妇女入馆。", impact: "广州成为欧洲对华贸易的唯一口岸，茶叶、生丝、瓷器自此出口，1784年美国商船「中国女王号」首航即来此；行商制一面造出伍崇曜、卢光岳辈的巨富与外债累累的破产行商，一面使中英冲突在关税、司法与公行三款内发酵，至1839年销烟之役即由此局而出。", figures: ["弘历"], place: "广州—澳门（今广东广州）", state: "清", sources: ["《粤海关志》卷五","《（乾隆）东华录》","马士《东印度公司对华贸易编年史（1635—1834）》"], tags: ["一口通商", "十三行"] }, related: ["cn--1685--x01", "cn--1751--p01"] },
  { id: "cn--1757--m01", track: "cn", year: 1757, yearApprox: false, dim: "military", weight: 3, title: "平阿睦尔撒纳之乱", summary: "再叛再定，天山北路尽入版图。", detail: { background: "1755年夏阿睦尔撒纳以不得为卫拉特四部之汗，于阿尔泰举兵，围乌里雅苏台，定边将军班第死之。", process: "1756至1757年（乾隆二十一、二十二年）清以成衮扎布、兆惠、富德分统巴里坤、乌鲁木齐两路进兵，穷追至伊犁、特克斯；阿睦尔撒纳败走哈萨克，旋入俄境，1757年秋以痘卒于俄城，清廷照会交换其尸验视。", impact: "天山北路底定，清于其地设伊犁将军、参赞大臣与都统，立屯田、驿站与军台，移民与锡伯、索伦、绿营之戍由是而起；准部诸部死于兵、疫与迁徙者甚众，现代学者据户口与军报推算其损失过半，而尽灭之说则为文士夸饰。", figures: ["兆惠", "阿睦尔撒纳", "弘历"], place: "伊犁—塔尔巴哈台（今新疆北部）", state: "清／准噶尔", sources: ["《清高宗实录》","《平定准噶尔方略》正编","曹树基《中国人口史》第五卷"], tags: ["准噶尔", "屯戍"] }, related: ["cn--1755--m01", "cn--1759--m01"] },
  { id: "cn--1759--m01", track: "cn", year: 1759, yearApprox: false, dim: "military", weight: 4, title: "平定大小和卓，取天山南路", summary: "黑水营解围，喀什噶尔、叶尔羌定。", detail: { background: "阿睦尔撒纳之乱时，被准部羁质的波罗尼都、霍集占兄弟（大、小和卓）归据喀什噶尔、叶尔羌，杀清使、据回城以抗。", process: "1758年（乾隆二十三年）冬兆惠以兵四千攻叶尔羌，被围于城东黑水营三月，掘冰得水、以马乳为食；1759年春富德率援军破围，两军合势定喀什噶尔、叶尔羌，二和卓西奔巴达克山，为其部所杀，传首京师。", impact: "天山南路各城入于清，以伯克制理回城事务而不世其官，驻参赞、办事大臣于喀什噶尔、叶尔羌、和阗、乌什，屯田与铸钱并行；自汉代西域都护之后，中原王朝对塔里木盆地的直接治理至此重建，近代中国的西北版图由此奠定。", figures: ["兆惠", "富德", "波罗尼都"], place: "喀什噶尔—叶尔羌（今新疆喀什—莎车）", state: "清", sources: ["《平定准噶尔方略》续编","《清史稿·兆惠传》","魏源《圣武记》卷三"], tags: ["回部", "西域"] }, related: ["cn--1757--m01"] },
  { id: "cn--1762--i01", track: "cn", year: 1762, yearApprox: false, dim: "institution", weight: 3, title: "户部通计民数", summary: "摊丁之后，户口统计始去其蔽。", detail: { background: "康熙五十一年滋生人丁永不加赋，雍正朝摊丁入亩，丁银并入田赋，人头税在制度上已不存在。", process: "1762年（乾隆二十七年）户部岁报全国民数二万万七百九十九万四千余口，诏此后每岁汇奏以「通计民数」为文，不再单列人丁若干；地方册报由丁口改为大小男妇合计。", impact: "税基与统计分离后，隐匿户口之动机大减，乾隆朝民数由一亿六千万增至近三万万，其中实际增殖与登报转实二者相杂；此制使国家掌握的人力数据首次接近真实规模，成为近代人口史研究的基准序列，也是人地压力、垦殖过度与流民问题的共同出发点。", figures: ["弘历"], place: "京师（今北京）", state: "清", sources: ["《清高宗实录》卷六七九","《清朝文献通考·户口》","何炳棣《中国人口研究》"], tags: ["户籍","统计"] }, related: ["cn--1712--i01", "cn--1723--i02"] },
  { id: "cn--1762--i02", track: "cn", year: 1762, yearApprox: false, dim: "institution", weight: 3, title: "设伊犁将军", summary: "节制全疆，军府治边之制定型。", detail: { background: "平定准噶尔与大小和卓后，天山南北驻军、屯田、征税、抚藩诸务纷杂，旧设参赞、办事大臣各分畛域。", process: "1762年（乾隆二十七年）置总统伊犁等处将军（伊犁将军）于惠远城，统驻疆满汉官兵，节制乌鲁木齐都统、塔尔巴哈台参赞、喀什噶尔参赞及各城办事、领队大臣；对哈萨克、布鲁特及中亚诸部交涉亦归其主持。", impact: "新疆自此成一军府行政区，与内地行省异制，军府、行政、理藩三元并立的边疆体制延续至1884年行省改建；军台、驿站与屯田网络把天山南北纳入全国统一边防体系，构成近代中国西北疆界的法理与实控基础。", figures: ["明瑞","弘历"], place: "伊犁惠远城（今新疆霍城）", state: "清", sources: ["《清高宗实录》卷六五一","永保《伊犁总统事略》","《大清会典事例·理藩院》"], tags: ["伊犁将军","军府制"] }, related: ["cn--1755--m01", "cn--1759--m01"] },
  { id: "cn--1763--f01", track: "cn", year: 1763, yearApprox: false, dim: "figure", weight: 1, title: "曹雪芹卒", summary: "悼红轩中增删十载，稿遗后四十回。", detail: { background: "曹雪芹名霑，祖籍辽阳，先世为内务府正白旗包衣，曾祖曹玺、祖曹寅历任江宁织造，雍正五年家败北归，晚年居京师西郊。", process: "约1763年或1764年（乾隆二十七年除夕或二十八年除夕，癸未、甲申两说）雪芹卒于西郊，年四十余或云五十许；敦诚挽诗有「牛鬼遗文悲李贺，鹿车荷锸葬刘伶」与「泪尽继以血，字字看来皆是血」之句。", impact: "其《石头记》前八十回以甲戌、庚辰、己卯诸抄本流传，身后经程伟元、高鹗补缀为一百二十回，成为白话长篇小说的高峰；「曹学」「红学」由此成一专门之学，20世纪新红学以胡适《红楼梦考证》为起点。", figures: ["曹雪芹","敦诚"], place: "京师西郊（今北京）", state: "清", sources: ["敦诚《四松堂集·挽曹雪芹》","甲戌本、庚辰本《石头记》批语","胡适《红楼梦考证》"], tags: ["曹雪芹","红楼梦"] }, related: ["cn--1791--c01"] },
  { id: "cn--1767--m01", track: "cn", year: 1767, yearApprox: false, dim: "military", weight: 3, title: "清缅之役", summary: "四征缅甸，损耗数万，以和议收场。", detail: { background: "缅甸东吁王朝雍籍牙统一上下缅地，属部木邦、耿马诸土司因边界细故相争，云贵总督杨应琚以师出有功冒奏。", process: "1767至1769年（乾隆三十二至三十四年）清四次用兵：刘藻、杨应琚、明瑞先后督师，明瑞率一万七千余众深入至阿瓦附近，1768年小猛育力战阵亡；傅恒、阿里衮率水陆兵三万出腾越，进至老官屯，会雨季瘴疠，军中病殁过半。", impact: "1769年老官屯停战，1770年后议定缅甸名义入贡而保持独立；清军前后战殁、病殁合计约二万至四万（魏源《圣武记》与清宫奏报数字出入较大）。此役暴露清军远程补给与应对热带疫病之弱，亦耗去国库盈余，所谓十全武功之虚实由此可议。", figures: ["傅恒","明瑞","弘历"], place: "云南腾越、老官屯（今缅甸克钦邦）", state: "清", sources: ["《清高宗实录》卷七八〇","《清史稿·傅恒传》","魏源《圣武记》卷十一"], tags: ["清缅战争","边疆"] }, related: ["cn--1762--i02"] },
  { id: "cn--1771--x01", track: "cn", year: 1771, yearApprox: false, dim: "explore", weight: 4, title: "土尔扈特东归", summary: "全署自伏尔加河东徙，到伊犁者七万余人。", detail: { background: "明末土尔扈特部西迁伏尔加河下游游牧，自汗阿玉奇以来与清廷通贡；俄征税、征丁、迫奉东正教，部众多有东归之议。", process: "1771年（乾隆三十六年）正月，汗渥巴锡（乌巴什）率所部举众东徙，出发人数诸书所记自六万余至十七万余不等，途中历俄军截击、哈萨克劫掠与痘疫饥渴，逾半年抵伊犁，存者七万余人。", impact: "清廷将各部安置于珠勒都斯、喀喇沙尔一带，赈米、赈马、封汗，渥巴锡与策伯克多尔济等入觐避暑山庄，高宗亲制《土尔扈特全部归顺记》《优恤土尔扈特部众记》二碑立于承德；哈萨克、布鲁特诸部由此益附，近代边疆民族迁徙与归属史亦以此为最著案例。", figures: ["渥巴锡","弘历"], place: "伏尔加河下游至伊犁（今俄罗斯、新疆）", state: "清", sources: ["《清高宗实录》卷八八八","承德《土尔扈特全部归顺记》碑","何秋涛《朔方备乘》"], tags: ["东归","土尔扈特"] }, related: ["cn--1712--x01"] },
  { id: "cn--1773--c01", track: "cn", year: 1773, yearApprox: false, dim: "culture", weight: 5, title: "开四库全书馆", summary: "辑天下书，寓禁于征。", detail: { background: "1771年安徽学政朱筠奏请校《永乐大典》、访购遗书，高宗以为遗书散佚宜及时搜罗。", process: "1773年（乾隆三十八年）二月开四库全书馆，皇子、大学士充总裁，纪昀、陆锡熊、戴震等为总纂，分经史子集四部，诏各省采进遗书，另立「存目」以待其不用者；至1782年写成第一部。", impact: "《四库全书》收书三千四百余种、七万九千余卷，另存目六千八百余种，为中国最大丛书；然馆臣删改、抽毁、全毁者相属，涉及明季边角事与「夷」「虏」字面之书几乎无一幸免，辑佚之功与禁毁之失并成，近人或径称乾隆朝之禁书为规模最大之一场文祸。", figures: ["纪昀","戴震","陆锡熊","弘历"], place: "京师（今北京）", state: "清", sources: ["《办理四库全书档案》","《四库全书总目》","郭伯恭《四库全书纂修考》"], tags: ["四库全书","丛书"] }, related: ["cn--1782--c01", "cn--1778--c01"] },
  { id: "cn--1774--m01", track: "cn", year: 1774, yearApprox: false, dim: "military", weight: 3, title: "王伦据临清", summary: "清水教起事，旬日众至数万。", detail: { background: "山东寿张一带清水教（白莲教支裔）以符水治病、授拳聚众，王伦为教首，蓄其徒为「手足」，密约起事。", process: "1774年（乾隆三十九年）八月王伦率数百人袭寿张、阳谷，戕官据临清，众至数万，以竹枪队攻城；巡抚徐绩、参赞大臣明亮先后率绿营进剿，九月临清复，王伦自焚死。", impact: "清军与平民死事者以千计，事后高宗严责地方官「习邪教而不之察」，山东、直隶大查教门；临清事件揭开乾隆后期秘密教门起事的连环局面，为1796年白莲教之乱提供了前例与清廷的教训。", figures: ["王伦","明亮"], place: "山东寿张、临清", state: "清", sources: ["《清高宗实录》卷九六一","《剿捕临清逆匪纪略》","《清史稿·王伦传》"], tags: ["教门起事","临清"] }, related: ["cn--1796--m01"] },
  { id: "cn--1776--m02", track: "cn", year: 1776, yearApprox: false, dim: "military", weight: 3, title: "第二次金川之役", summary: "再征两金川，兵费近九百万两。", detail: { background: "第一次金川之役后，大小金川土司索诺木、僧格桑仍兼并邻屯、拒还所掠，清以阿尔泰、文绶先后经理无效。", process: "1776至1779年（乾隆四十一至四十四年）二次用兵，阿桂、海兰察率健锐、火器营满汉兵先后七万分道进逼，攻克噶喇依、勒围诸坚碉；1779年索诺木、僧格桑出降，磔于京师，于其地设美诺、阿尔古两厅，后并为懋功屯务厅，改土归屯。", impact: "此役历时四年余，清军战殁将弁数百、兵丁万余，耗银约九百万两（《平定两金川方略》与户部核销数），为十全武功中耗费最钜者；攻坚碉、涉雪山之经验暴露了远征极限，而川西边地改屯亦使当地土司社会结构瓦解。", figures: ["阿桂","海兰察"], place: "四川大金川、小金川（今金川、丹巴）", state: "清", sources: ["《御批平定两金川方略》","《清史稿·阿桂传》","魏源《圣武记》卷十二"], tags: ["金川之役","改土归流"] }, related: ["cn--1747--m01", "cn--1725--i01"] },
  { id: "cn--1777--f01", track: "cn", year: 1777, yearApprox: false, dim: "figure", weight: 1, title: "戴震卒", summary: "由字以通词，由词以通道。", detail: { background: "戴震（1724—1777）字东原，安徽休宁人，少从江永问学，以算学、声音、训诂通经，乾隆二十五年举人，三十八年成进士。", process: "1777年（乾隆四十二年）五月戴震卒于京师，年五十五；遗著《孟子字义疏证》以「以理杀人」之论针砭程朱末流，《原善》《勾股割圆记》并传，四库馆中任经部纂修。", impact: "其「由字以通其词，由词以通其道」的训诂路径，与段玉裁、王念孙父子相承，为乾嘉学派的骨干，章太炎、梁启超、胡适皆推为清代思想之最有力者；《孟子字义疏证》在近代被读作反理学的自然人性论。", figures: ["戴震","段玉裁","王念孙"], place: "京师（今北京）", state: "清", sources: ["段玉裁《戴东原先生年谱》","《戴东原集》","梁启超《中国近三百年学术史》"], tags: ["戴震","考据"] }, related: ["cn--1815--c01", "cn--1773--c01"] },
  { id: "cn--1778--c01", track: "cn", year: 1778, yearApprox: false, dim: "culture", weight: 4, title: "禁毁违碍书籍", summary: "抽毁全毁，禁书几三千种。", detail: { background: "四库馆开而书禁随之，1774年（乾隆三十九年）八月谕各省所有「关于彝虏悖逆之词、陆沉之迹」诸书限缴毁，浙江巡抚三宝以《国初先正遗集》诸案应。", process: "1778年（乾隆四十三年）再申禁毁之令，明人遗集、地方志、碑刻中干碍字面者一体删改，或全毁、或抽毁、或删削；自是迄乾隆末先后禁毁二十余轮，据《禁书总目》《应禁书目》著录被毁书三千余种、六七百万卷册（学界对卷数估计出入较大）。", impact: "宋以来野史、明实录别本、边角地理书因此大量失传，清代士人多避史事而专攻经、小学，考据之盛与文网之密同时成就；近代论四库馆「寓禁于征」者，多以本轮禁毁为其证据。", figures: ["弘历","陆锡熊"], place: "京师（今北京）", state: "清", sources: ["《办理四库全书档案》","《禁书总目》《应禁书目》","郭伯恭《四库全书纂修考》"], tags: ["禁书","文字狱"] }, related: ["cn--1773--c01", "cn--1790--a01"] },
  { id: "cn--1782--c01", track: "cn", year: 1782, yearApprox: false, dim: "culture", weight: 4, title: "《四库全书》写成", summary: "七阁分贮，写校十载。", detail: { background: "1773年开馆后，辑佚、抄录、校雠分任其难，翰林院与各地写手千人抄写，纪昀、陆锡熊总其成。", process: "1782年（乾隆四十七年）正月第一部《四库全书》写成，凡三万六千册、七万九千余卷，贮紫禁城文渊阁；此后陆续写成分贮圆明园文源、盛京文溯、热河文津三阁与扬州文汇、镇江文宗、杭州文澜三阁，合称北四阁、南三阁。", impact: "丛书以经史子集四部分类，为古籍最完整的存录与书目系统，近代影印与提要之学由此而兴；然抄本删改底本极多，且文源阁本毁于1860年之役、文汇文宗毁于太平天国兵火、文澜残阙后经钱学嘉、张宗祥先后补抄，今存四部，其存毁本身即为文献史之大事件。", figures: ["纪昀","陆锡熊"], place: "京师文渊阁（今北京故宫）", state: "清", sources: ["《四库全书总目》","文渊阁《四库全书》影印本说明","郭伯恭《四库全书纂修考》"], tags: ["四库全书","藏书"] }, related: ["cn--1773--c01", "cn--1778--c01"] },
  { id: "cn--1786--d01", track: "cn", year: 1786, yearApprox: false, dim: "disaster", weight: 3, title: "泸定磨西地震", summary: "川西强震，大渡河断流十日。", detail: { background: "川西鲜水河、大雪山一带断裂带历史上强震频繁，乾隆年间泸定、磨西已有小震记载。", process: "1786年6月1日（乾隆五十一年五月十日）四川泸定磨西发生约7.7级强震，烈度十度，泸定、化林坪城垣、庙宇、桥铺尽圮；大渡河为崖石崩坠壅塞，断流十日，积水既满而溃。", impact: "溃水沿大渡河下注岷江、大江，淹没嘉州（今乐山）、叙州、嘉定沿江州县，漂没、压毙人数诸书所记自二万余口至四万不等，现代学者据沿江志书推定当以二万至三万为近；此为中国史上由滑坡堵江引发链式洪水致死的典型例证，国家地震局《中国历史强震目录》据此定为清代川西最重震灾。", figures: ["弘历"], place: "四川泸定、嘉州（今泸定、乐山）", state: "清", sources: ["国家地震局《中国历史强震目录》","《清史稿·灾异志》","（乾隆）《四川通志·祥异》"], tags: ["地震","堰塞湖"] }, related: ["cn--1668--d01", "cn--1739--d01"] },
  { id: "cn--1786--m01", track: "cn", year: 1786, yearApprox: false, dim: "military", weight: 3, title: "林爽文起事", summary: "天地会陷彰化、诸罗，两年平定。", detail: { background: "台湾漳泉、闽客分类械斗频仍，天地会以「反清复明」号召，彰化一带会众数以万计。", process: "1786年（乾隆五十一年）十一月彰化天地会首领林爽文劫狱起事，众至十万，先后陷彰化、诸罗、凤山；清以闽浙总督常青、参赞大臣恒瑞督师，总兵柴大纪守诸罗，1787年福康安率内地兵万余渡台，1788年正月擒林爽文于老衢崎，磔于京师。", impact: "诸罗被围十月，守城军民死伤以万计，战后清改诸罗为嘉义、增设屯丁以抚义民，台湾镇改更番调防之制，闽粤渡台禁例部分弛废；此为清代台湾首次大规模民变，此后张丙、戴万生诸案皆循其例。", figures: ["林爽文","福康安","柴大纪"], place: "台湾彰化、诸罗（今嘉义）", state: "清", sources: ["《（乾隆）平定台湾案》","《清高宗实录》卷一二七〇","《清史稿·福康安传》"], tags: ["天地会","台湾"] }, related: ["cn--1683--m01"] },
  { id: "cn--1790--a01", track: "cn", year: 1790, yearApprox: false, dim: "art", weight: 4, title: "徽班进京祝厘", summary: "三庆入都，四大徽班自此始。", detail: { background: "扬州、安庆一带昆、弋、梆子诸腔在盐班中合流，徽班以二黄、西皮兼擅众调，名旦高朗亭已声动南北。", process: "1790年（乾隆五十五年）值高宗八旬万寿，两淮盐商醵资延三庆班入京祝厘，其后四喜、春台、和春三班相继入都，合称四大徽班；诸班于前门、大栅栏一带戏园、酒楼搬演，与京中秦腔、罗罗腔互相吸收。", impact: "徽汉合流、京音入曲由此定调，历经嘉道年间熔铸而为京剧，其后二百年北京成为全国戏曲的评判中心；徽班进京亦使盐商、票友、戏园与报馆结成近代都市演艺市场的雏形。", figures: ["高朗亭","弘历"], place: "京师（今北京）", state: "清", sources: ["（清）吴长元《燕兰小谱》","（清）吴太初《听春新咏》","《大清会典事例·乐部》"], tags: ["徽班","京剧"] }, related: ["cn--1778--c01"] },
  { id: "cn--1791--c01", track: "cn", year: 1791, yearApprox: false, dim: "culture", weight: 5, title: "《红楼梦》程甲本", summary: "活字印一百二十回，小说始广流传。", detail: { background: "曹雪芹《石头记》前八十回仅以抄本流传，脂砚斋评语与残本互异，求全者众而不可得。", process: "1791年（乾隆五十六年）冬程伟元、高鹗以活字排印一百二十回本《红楼梦》（程甲本），次年又改订重排（程乙本），序称先于藏家及鼓担处得后四十残稿，「延师友细加厘剔，截长补短，合成一部」。", impact: "此后《红楼梦》以印本遍及士林市井，翻刻、续书、评点诸本层出，王国维《红楼梦评论》（1904）以叔本华美学释之，开小说批评之新局；程高本后四十回之真伪与优劣至今聚讼，为近代红学最核心的文本问题。", figures: ["程伟元","高鹗","曹雪芹"], place: "京师（今北京）", state: "清", sources: ["程甲本《红楼梦》程伟元、高鹗序","中国艺术研究院《红楼梦》校注本前言","胡适《红楼梦考证》"], tags: ["红楼梦","刻本"] }, related: ["cn--1763--f01"] },
  { id: "cn--1793--i01", track: "cn", year: 1793, yearApprox: false, dim: "institution", weight: 4, title: "藏内善后章程二十九条", summary: "金瓶掣签，驻藏大臣总理藏务。", detail: { background: "1788、1791年廓尔喀两次入侵后藏，扎什伦布寺被掠，清以福康安率军入藏反击，逾界逼阳布。", process: "1793年（乾隆五十八年）福康安等议定《钦定藏内善后章程》二十九条颁行：驻藏大臣与达赖、班禅位次相等，共同督办藏内事务；噶伦以下官缺归驻藏大臣铨叙；边界贸易、铸币、驿站、驻军俱定章程；达赖、班禅及各大呼图克图转世以金奔巴瓶掣签，由驻藏大臣监临。", impact: "此章程确立中央对西藏行政、军事、外交与宗教继承监管之定制，金瓶掣签自此为达赖、班禅转世的法定程序，历嘉道咸同光相沿不废（少数蒙藏合词奏准免于掣签）；廓尔喀此后入贡，喜马拉雅边地维持近百年秩序。", figures: ["福康安","八世达赖","弘历"], place: "拉萨（今西藏拉萨）", state: "清", sources: ["《卫藏通志》","《御制十全记》","牙含章《达赖喇嘛传》"], tags: ["驻藏大臣","金瓶掣签"] }, related: ["cn--1751--i01", "cn--1793--p01"] },
  { id: "cn--1793--p01", track: "cn", year: 1793, yearApprox: false, dim: "politics", weight: 5, title: "马戛尔尼使团", summary: "以祝厘为名求通商，跪礼与货单俱阻。", detail: { background: "英为开辟中国市场、求通商与设使之便，东印度公司拟派使团，广州商馆先荐熟悉华情者。", process: "1793年（乾隆五十八年）英使马戛尔尼率「狮子」号等舰至热河，呈国书，请派使驻京、开宁波舟山天津等口、准英人在京贸易、明定税则、减免加征；高宗以「天朝物产丰盈，无所不有」复英王，仅准仍就澳门、广州贸易，跪拜礼之争未决，使团八月觐见后即遣归。", impact: "使团一无所成，中英双方在礼制、贸易与法理认知上的落差暴露无遗；随员斯当东、巴罗对清军装备、海岸与河道所作的观察，成为鸦片战争前西方判断中国虚弱的一手依据。中方亦未因这次接触获得任何制度反馈，通商体制之调整延宕至炮口之下。", figures: ["马戛尔尼","弘历"], place: "热河避暑山庄、京师（今河北承德、北京）", state: "清", sources: ["斯当东《英使谒见乾隆纪实》","《清高宗实录》卷一四二三","马士《中华帝国对外关系史》卷一"], tags: ["使团","中西"] }, related: ["cn--1757--e01", "cn--1793--i01"] },
  { id: "cn--1795--p01", track: "cn", year: 1795, yearApprox: false, dim: "politics", weight: 3, title: "高宗内禅仁宗即位", summary: "归政仍训政，和珅用事如故。", detail: { background: "高宗以康熙六十一年在位最久，1790年曾言不敢逾之，1795年九月明诏立皇十五子颙琰为皇太子。", process: "1795年十月（乾隆六十年）高宗禅位于颙琰，自称太上皇帝仍训政，诏旨多出自太上；仁宗改元嘉庆，侍班问安，而和珅仍掌军机处、内务府与崇文门，出入宫禁，朝政不出于上新君。", impact: "此次内禅为中国史上最后一次「太上皇训政」，它延续了皇权交接的不透明，也放大了权臣与言路之争；次年正月高宗崩，仁宗迅速诛和珅，嘉庆朝即以「咸与维新」之诏开局，而制度更张终无所成。", figures: ["弘历","颙琰","和珅"], place: "京师（今北京）", state: "清", sources: ["《清高宗实录》卷一四七三","《清仁宗实录》卷一","《（嘉庆）东华录》"], tags: ["内禅","嘉庆"] }, related: ["cn--1799--p01"] },
  { id: "cn--1795--s01", track: "cn", year: 1795, yearApprox: false, dim: "science", weight: 3, title: "阮元辑《畴人传》", summary: "为历算家立传，中算始有谱系。", detail: { background: "乾嘉学者以算学、天文诂经，然历算诸家事迹散见史志，无专书可稽。", process: "1795年（乾隆六十年）阮元辑成《畴人传》四十六卷，自上古容成、羲和至清初梅文鼎、年希尧，为历代历算、天文学家四百余人立传并附论断，焦循、李锐、陈美壮同辑，后复有续编兼收西人格里高、第谷之说。", impact: "此书首次以学术史方式整理中国天算传承，直接推动嘉道咸间算书辑佚与李锐治《九章》、骆腾凤诸家之业；阮元又以「中历失传、西人窃取」之说解中西历算关系，成为晚清历法之争中守旧一方的理论凭据。", figures: ["阮元","焦循","李锐"], place: "浙江（今杭州）", state: "清", sources: ["阮元《畴人传》","《清史稿·艺术传》","（清）焦循《雕菰楼集》"], tags: ["畴人传","历算"] }, related: ["cn--1773--c01"] },
  { id: "cn--1796--m01", track: "cn", year: 1796, yearApprox: false, dim: "military", weight: 5, title: "白莲教之乱", summary: "川楚陕教乱九年，耗银约二万万两。", detail: { background: "乾隆末川、楚、陕边山棚民稠密，白莲教以「真空家乡、无生父母」与「弥勒下生」纠众，地方查拿株累，遂密约起事。", process: "1796年（嘉庆元年）三月湖北枝江、襄阳王聪儿、张汉潮等先起，四川达州徐天德、冷天禄应之，众至数十万，转流动于川楚陕甘豫五省；清以额勒登保、德楞泰、明亮督师，行坚壁清野、查户立寨、禁粮入山之策，至1804年肃清。", impact: "乱事历时九年，清耗银约二万万两（户部核销与《剿平白莲教邪匪档案》所记），将弁阵亡、被戕数以千计，被毁州县以百数，五省边区人口锐减；兵源自此由八旗、绿营倚向乡勇练丁，晚清勇营之制与中央财政之颓，多可溯于此役。", figures: ["王聪儿","徐天德","额勒登保","颙琰"], place: "川楚陕边区（今湖北、四川、陕西）", state: "清", sources: ["中国第一历史档案馆藏《剿捕白莲教邪匪档案》","《清仁宗实录》","魏源《圣武记》卷九"], tags: ["白莲教","教乱"] }, related: ["cn--1774--m01", "cn--1750--e01"] },
  { id: "cn--1799--p01", track: "cn", year: 1799, yearApprox: false, dim: "politics", weight: 4, title: "诛和珅", summary: "二十条罪款抄家，嘉庆除权臣。", detail: { background: "和珅自乾隆四十年后以军机大臣、户部尚书掌财权，兼领内务府、崇文门，卖官聚敛、壅蔽言路，仁早在藩邸已知其弊。", process: "1799年（嘉庆四年）正月初三日高宗崩，仁宗即日革和珅步军统领与职任下狱，正月十九日宣布二十条大罪，赐自尽，籍其家；抄产清单著录房屋、当铺、田地、金、银、珠宝，总值诸说自八亿两至十一亿两不等，京师遂有「和珅跌倒，嘉庆吃饱」之谚。", impact: "和珅案是清代权臣最盛最衰于一朝的了断，其贪渎规模亦折射乾隆后期捐纳、奏销与河工财政之弊；然仁宗去一和珅而未能改其制度，吏治、教乱、河患与财源之困一仍其旧，嘉庆朝「守成而无更张」之局由此定型。", figures: ["和珅","颙琰"], place: "京师（今北京）", state: "清", sources: ["《清仁宗实录》卷三八","《和珅犯罪全案档》","（清）薛福成《庸盦笔记》"], tags: ["和珅","抄家"] }, related: ["cn--1795--p01"] },
  { id: "cn--1804--f01", track: "cn", year: 1804, yearApprox: false, dim: "figure", weight: 1, title: "钱大昕卒", summary: "由声音文字以通史，乾嘉史学之冠。", detail: { background: "钱大昕（1728—1804）字晓徵，号竹汀，江苏嘉定人，乾隆十九年进士，改翰林，历典广东、江南乡试及提学诸职。", process: "1804年（嘉庆九年）十月钱大昕卒于苏州紫阳书院，年七十七；先后主讲钟书、娄东、紫阳诸书院近三十年，著《廿二史考异》百卷、《十驾斋养新录》、《元史氏族表》《元史艺文志》《疑年录》与《潜研堂文集》。", impact: "其以声韵、地理、职官、氏族、历算互证正史讹误，不必空言义理而所得至多，与王鸣盛、赵翼并称乾嘉史学三大家而为最精审者；近代王国维、陈垣、陈寅恪治史，皆以钱氏《元史》诸作为可循之正轨。", figures: ["钱大昕"], place: "江苏苏州（今苏州）", state: "清", sources: ["严荣《钱竹汀先生年谱》","钱大昕《廿二史考异》","《清史稿·儒林传》"], tags: ["钱大昕","史学考异"] }, related: ["cn--1777--f01", "cn--1814--f01"] },
  { id: "cn--1805--f01", track: "cn", year: 1805, yearApprox: false, dim: "figure", weight: 1, title: "纪昀卒", summary: "总纂四库二十年，退而撰《阅微》。", detail: { background: "纪昀（1724—1805）字晓岚，直隶献县人，乾隆十九年进士，入翰林，以文辞淹雅为高宗所知。", process: "1805年（嘉庆十年）二月初六日纪昀卒于京师，年八十二，谥文达；自1773年四库馆开，任总纂官者逾十年，《四库全书总目》二千余条提要由其手定，晚年成《阅微草堂笔记》五种二十四卷。", impact: "提要之学以考辨源流、条贯得失为职，成为后世治古籍者之门径；《阅微》以质木之笔写神怪，与《聊斋》异趣而开笔记小说之一格。然纪昀以馆臣之身份删改群书、以汉学家立场驳宋儒，亦为近代学者指陈「四库之失」时的主要对象。", figures: ["纪昀"], place: "京师（今北京）", state: "清", sources: ["《清史稿·纪昀传》","《四库全书总目》","纪昀《阅微草堂笔记》"], tags: ["纪昀","四库全书"] }, related: ["cn--1773--c01", "cn--1782--c01"] },
  { id: "cn--1807--x01", track: "cn", year: 1807, yearApprox: false, dim: "explore", weight: 3, title: "马礼逊抵广州", summary: "新教入华之始，字典成而中西始通。", detail: { background: "1807年伦敦传道会遣马礼逊赴粤，时广州仅许行商与夷目居止，传教为清律例所明禁。", process: "1807年9月4日马礼逊抵广州，初匿居英商馆中习粤语与官话，1809年受雇为东印度公司广州译员，1810年译出《使徒行传》，1813年与米怜共成新约全书，改名《神天圣书》。", impact: "此为基督教新教入华之始；其与米怜合辑《华英字典》三卷（1815至1823年麻六甲刊）为第一部系统汉英工具书，其后数十年西洋传教士、商务与外交人员皆倚之以通语言，汉字铅字与石版印刷诸术亦由澳门、麻六甲一线渐入中国沿边。", figures: ["马礼逊","米怜"], place: "广州（今广州）", state: "清", sources: ["马礼逊《华英字典》","马士《中华帝国对外关系史》卷一","东印度公司广州商馆档案"], tags: ["新教","中西交通"] }, related: ["cn--1721--c01"] },
  { id: "cn--1813--m01", track: "cn", year: 1813, yearApprox: false, dim: "military", weight: 4, title: "天理教犯京师", summary: "变起禁门内，京师大戒。", detail: { background: "白莲教乱甫平，直隶、山东、河南一带八卦教、天理教仍秘密传习，以「白阳天王」相号召。", process: "1813年（嘉庆十八年）九月十五日，天理教首林清率二百余人由内监为导，分自东华、西华门攻入紫禁城，与侍卫、健锐营巷战于隆宗门、苍震门一带，杀伤兵民数十人，两日始定；同月河南滑县李文成、牛亮臣据城起事，十一月被那彦成等督师攻破，城内死者数万。", impact: "仁宗下诏罪己，谓「变生肘腋，旷古所无」，严谕直隶、山东、河南查办教门，立专条治习教之罪；此次事件暴露八旗、绿营驻防与宫中门禁之全不可恃，京营武备自此更形废弛，畿辅秘密宗教终清之世未能尽绝。", figures: ["林清","李文成","颙琰"], place: "京师、河南滑县", state: "清", sources: ["《清仁宗实录》卷二七九","那彦成《那文毅公奏议》","《（嘉庆）东华录》"], tags: ["天理教","禁门之变"] }, related: ["cn--1796--m01", "cn--1774--m01"] },
  { id: "cn--1814--f01", track: "cn", year: 1814, yearApprox: false, dim: "figure", weight: 1, title: "赵翼卒", summary: "以史证史，论制度风俗之变。", detail: { background: "赵翼（1727—1814）字云崧，号瓯北，江苏阳湖人，乾隆二十六年丁巳科探花及第，官至广西太平道，主讲安定、龙城诸书院。", process: "1814年（嘉庆十九年）十二月赵翼卒于里第，年八十有八；所著《廿二史札记》三十六卷，以本史互证，论汉初郡国、唐代女祸、宋代科第、明代厂卫与元末吏治诸题，别辑《陔余丛考》、诗话与诗集行世。", impact: "其不以琐细校勘为足，而专标历史大势与制度得失，为乾嘉史学中最具问题意识的一种，梁启超、吕思勉皆推为近代论史之先声；「世道江河，不知其几变矣」的演化眼光，亦开后来以制度与风俗写史一路。", figures: ["赵翼"], place: "江苏阳湖（今常州）", state: "清", sources: ["赵翼《廿二史札记》","《清史稿·文苑传》","赵翼《陔余丛考》"], tags: ["赵翼","史学"] }, related: ["cn--1804--f01"] },
  { id: "cn--1815--c01", track: "cn", year: 1815, yearApprox: false, dim: "culture", weight: 3, title: "《说文解字注》成书", summary: "段注出而说文学成一宗。", detail: { background: "段玉裁（1735—1815）字若膺，江苏金坛人，戴震弟子，令甘肃、川中十余年，退老吴门，积数十年之力撰此书。", process: "1815年（嘉庆二十年）《说文解字注》三十卷成并于苏州开雕，其书以许慎为宗而校以经传、诸子与音韵，明「以字知语、以语知道」之序，重定转注、假借之界说，并古音为十七部。", impact: "自是「说文学」由附庸而为专门，桂馥《说文解字义证》、王筠《说文句读》、朱骏声《说文通训定声》相继并出，号为段氏四大家；近代章太炎、黄侃、杨树达之小学，以及甲骨文、金文考释之业，皆以此书为入门之径。", figures: ["段玉裁"], place: "江苏苏州（今苏州）", state: "清", sources: ["段玉裁《说文解字注》","《清史稿·儒林传》","梁启超《中国近三百年学术史》"], tags: ["说文","小学"] }, related: ["cn--1777--f01"] },
  { id: "cn--1819--a01", track: "cn", year: 1819, yearApprox: false, dim: "art", weight: 3, title: "焦循撰《花部农谭》", summary: "为村庙乱弹立论，花部始登大雅。", detail: { background: "乾嘉之际昆腔（雅部）日衰，梆子、皮黄、弦索诸「花部」乱弹盛行于村社庙会。", process: "1819年（嘉庆二十四年）焦循（1763—1820，江苏甘泉人）成《花部农谭》一卷，著录花部剧目二十三种，记其词意与演出，谓其「皆合于元人体制」，观之足以动人，而昆山腔「词不必可观，听之使人厌倦」。", impact: "此为最早系统论列地方戏并予其士人之认可的专著，与徽班进京、乱弹日盛之声势相应；近代戏曲史家多以此书为京剧取得正统地位的思想前导，焦循并以数学、易学名世，其论曲亦开后来以民俗入学术之风。", figures: ["焦循"], place: "江苏甘泉（今扬州）", state: "清", sources: ["焦循《花部农谭》","《清史稿·儒林传》","周贻白《中国戏曲史长编》"], tags: ["花部","戏曲"] }, related: ["cn--1790--a01"] },
  { id: "cn--1820--d01", track: "cn", year: 1820, yearApprox: false, dim: "disaster", weight: 3, title: "霍乱大疫东渐", summary: "边省与沿江同时大疫，死者相属于路。", detail: { background: "嘉庆末川楚用兵之后，云贵、两广商路频繁，疫气自西南边地随人行北渐东移。", process: "1820年（嘉庆二十五年）夏秋，时人所谓「时疫」「转筋霍乱」自云南、广东同时大举流行，直隶、山东、浙江沿江沿海州县继之，地方志多载一乡一邑死者十之四五；民间以藿香正气诸方、针刺放水救治，官府施药施棺而已。", impact: "现代疾病史研究据此定为霍乱自南亚沿陆海两路传入中国并立足之始（与1817至1824年之第一次世界性大流行相合），疫后「霍乱」遂成南方岁时常见之病；清廷无检疫与疫政之设，其后果之一即为咸丰同治间西医与海关检疫制度之输入。", figures: ["颙琰"], place: "云南、广东至直隶、浙江", state: "清", sources: ["《清史稿·灾异志》","（清）王孟英《霍乱论》","范行准《中国病史新义》"], tags: ["霍乱","时疫"] }, related: ["cn--1820--p01"] },
  { id: "cn--1820--p01", track: "cn", year: 1820, yearApprox: false, dim: "politics", weight: 2, title: "宣宗即位", summary: "以节俭立政，值中外之大局。", detail: { background: "仁宗于嘉庆二十五年七月巡幸木兰，八月二十二日崩于避暑山庄烟波致爽殿。", process: "1820年（嘉庆二十五年）八月皇二子旻宁即位于山庄，九月还京，改元道光；即位诏以崇俭黜浮为纲，裁各省贡献方物、罢巡幸供应，以曹振镛、文孚掌枢廷。", impact: "宣宗在位三十年，值鸦片战争、五口通商与太平军兴之开局，其性苛俭而怯于更张，河工、盐政、军政皆循其旧，士论有「道光朝之局促」之讥；军机处权势与言路之收缩，亦使咸丰、同治以降亲贵与督抚分权之势渐成。", figures: ["旻宁","曹振镛"], place: "热河、京师（今河北承德、北京）", state: "清", sources: ["《清仁宗实录》卷三六二","《清宣宗实录》卷七","《（道光）东华录》"], tags: ["宣宗","道光"] }, related: ["cn--1823--e01"] },
  { id: "cn--1823--d01", track: "cn", year: 1823, yearApprox: false, dim: "disaster", weight: 3, title: "江南大水", summary: "太湖溢而苏松常镇成泽国。", detail: { background: "道光三年入夏以来江淮梅雨逾常，太湖、淀山湖泄道壅于民圩，江水无所宣受。", process: "1823年（道光三年）六月至八月，江苏、安徽、浙江连绵暴雨，苏、松、常、镇、太四府一州农田多被淹，灾民以数百万计；清廷蠲缓漕赋、截留漕粮平粜，令地方绅商捐米助赈，浙江山洪同时毁富阳、余杭民舍无算。", impact: "此次水灾使江南省份财政与漕运积弊尽出，办赈中官力不足而倚绅商，开后来义赈与商办善堂之例；灾后陶澍、贺长龄诸人入两江任事，漕运改海运、盐政改票法诸议皆起于此，江南士大夫之经世思潮亦由灾政而发。", figures: ["陶澍"], place: "江苏、安徽、浙江", state: "清", sources: ["《清史稿·灾异志》","《（道光）上谕档》","《中国近五百年旱涝分布图集》"], tags: ["水灾","江南"] }, related: ["cn--1826--i01"] },
  { id: "cn--1823--e01", track: "cn", year: 1823, yearApprox: false, dim: "economy", weight: 5, title: "平遥创票号", summary: "汇兑代解银，商债可千里取偿。", detail: { background: "乾嘉以降，商贾贸易与各省关款项须凭现银长途转运，道路不靖、运费与熔折之耗日重。", process: "约1823年（道光三年前后，学界另有嘉庆末与1800年前后诸说）山西平遥西裕成颜料庄改设「日升昌」票号，首创凭票汇兑、认票不认人之制，以密押、水印与分号相互稽核；此后平遥、祁县、太谷诸村票号数十家，分号遍布京师、天津、汉口、西安、成都、归化、恰克图。", impact: "全国资金调拨由运银转为汇兑，商业信用与金融网络为之一变，山西商人遂执国内金融之牛耳数十年；票号后承汇京饷、协饷乃至对外赔款，与国家财政相绑定，1911年后因官款易途与银行竞争而骤衰，其兴亡即为近代金融权转移之标本。", figures: ["雷履泰"], place: "山西平遥（今平遥）", state: "清", sources: ["（光绪）《平遥县志》","黄鉴晖《山西票号史料》","《清宣宗实录》卷四七"], tags: ["票号","晋商"] }, related: ["cn--1835--e01"] },
  { id: "cn--1823--s01", track: "cn", year: 1823, yearApprox: false, dim: "science", weight: 2, title: "《神天圣书》全译刊行", summary: "西法印刷与汉字铅字随之东来。", detail: { background: "马礼逊自1807年在粤译经，米怜在麻六甲设印刷所，中英士人合作写版铸字。", process: "1823年马礼逊、米怜合译之《神天圣书》（新旧约全书）在麻六甲刊成，以西式金属活字排印，汉字与英译对照刊行；此前《华英字典》第一卷已于1815年印出。", impact: "此译本为汉语圣经之完整起点，其「上帝」「天国」等译名后为太平天国之教义所袭用；同时该印刷所铸汉字金属活字并用石印之法，使中文之机械复制成为可能；1843年英传教士在上海设墨海书馆，六十年代土山湾印书馆继之，1897年商务印书馆以机器活字印书起家，皆循此技术路线，是为近代出版业之前提。", figures: ["马礼逊","米怜"], place: "麻六甲（今马来西亚马六甲）", state: "清", sources: ["马礼逊、米怜合译《神天圣书》","马礼逊《华英字典》","马士《中华帝国对外关系史》卷一"], tags: ["译经","印刷"] }, related: ["cn--1807--x01"] },
  { id: "cn--1826--c01", track: "cn", year: 1826, yearApprox: false, dim: "culture", weight: 3, title: "《皇朝经世文编》辑成", summary: "辑一代之文奏，倡经世之学。", detail: { background: "乾嘉考据极盛之际，一二任事之员以吏治、漕河、盐政、边防为念，欲以文字开其风气。", process: "1826年（道光六年）魏源（1794—1857）受江苏布政使贺长龄之嘱，辑国初至道光初诸家奏议文集成《皇朝经世文编》一百二十卷，分学术、治体与吏户礼兵刑工八门，录文六千余篇，自序谓「书以曾未尝用，非徒以文也」。", impact: "此书使「经世致用」由少数人之倡而为一朝士风之枢纽，龚自珍、林则徐、包世臣、冯桂芬皆由此入；同光间续编、三编、四编相承不辍，其分门辑文之体例亦为近代政论集与教科文书所本。", figures: ["魏源","贺长龄"], place: "江苏苏州（今苏州）", state: "清", sources: ["贺长龄、魏源辑《皇朝经世文编》","《清史稿·魏源传》","魏源《魏源集·军储篇》"], tags: ["经世","文集"] }, related: ["cn--1826--i01", "cn--1823--d01"] },
  { id: "cn--1826--i01", track: "cn", year: 1826, yearApprox: false, dim: "institution", weight: 5, title: "漕粮改由海运", summary: "沙船出吴淞，粮道别开一途。", detail: { background: "嘉庆末黄河屡决、洪泽湖高家堰漫溢，运河与御道节节淤阻，漕船浅滞不能北上。", process: "1826年（道光六年）行首届海运漕粮：雇江浙商船千数百艘，自上海、刘河口岸出海，循黑水洋北上抵天津，运米豆一百六十余万石，由直隶接运通州；协办大学士英和倡其议，江浙两省督抚与地方绅商董其事；所运米石除水渍偷漏之折耗外，抵津实数与起运数相去无几。", impact: "自此河运、海运并行而海运日占优势，上海因漕船、沙船云集一跃为东南米豆、棉布、油糖之总汇，其港口地位实基于此；咸丰末漕粮全归海运，同治十一年轮船招商局即承此观念与航线而立，可视为近代航运业之远因。", figures: ["英和","旻宁"], place: "上海至天津（今上海、天津）", state: "清", sources: ["《清宣宗实录》卷一〇〇","《（道光）东华录》","《皇朝经世文编·户政·漕运》"], tags: ["海运","漕运"] }, related: ["cn--1823--d01", "cn--1826--c01"] },
  { id: "cn--1826--m01", track: "cn", year: 1826, yearApprox: false, dim: "military", weight: 3, title: "张格尔之乱", summary: "和卓后裔入卡，南疆三城复扰。", detail: { background: "乾隆平大小和卓后，其族裔逃居浩罕，屡借「圣战」之名谋入天山南路。", process: "1826年（道光六年）张格尔诱布鲁特与浩罕兵入边，陷喀什噶尔回城，扰英吉沙尔、叶尔羌、和阗；清以长龄为扬威将军督师，调伊犁、乌鲁木齐及内地满汉兵三四万进剿，1827年擒张格尔解京师处死。", impact: "此乱使浩罕汗国自此介入南疆事务，和卓后裔之入卡在1830、1832、1847、1852年间相续不断，边费岁增；伊犁军府与卡伦巡塞之制暴露其弊，同治四年阿古柏随入疆之局及光绪三年左宗棠收疆，其地理与部族条件均可溯至是役。", figures: ["张格尔","长龄"], place: "喀什噶尔、叶尔羌（今喀什、莎车）", state: "清", sources: ["《清史稿·长龄传》","《（道光）东华录》","姚莹《康輶纪行》"], tags: ["南疆","和卓"] }, related: ["cn--1759--m01", "cn--1762--i02"] },
  { id: "cn--1832--c01", track: "cn", year: 1832, yearApprox: false, dim: "culture", weight: 2, title: "梁发刻《劝世良言》", summary: "一册布道书，伏后日太平军之因。", detail: { background: "梁发（1789—1855）广东高明人，刻工出身，从马礼逊习教理，1816年受洗为华人最早之新教徒牧师之一。", process: "1832年（道光十二年）梁发辑《劝世良言》九卷刻于广州，以浅显中文击偶像、祀祖与捐庙之俗，劝人独拜上帝；书成由传教士与华人在粤、港、闽一带分送数千部，粤省官府迭次查禁。", impact: "广东花县举人洪秀全1836年在粤偶得此书，1843年应试不第后复读，自谓恍然醒悟，遂立拜上帝会，其「天父」「天王」之称与政教结构皆源出于此；一部边缘布道小册引出持续十余年、死亡以千万计之战乱，为近代中西文字接触之后果最重者一例。", figures: ["梁发","马礼逊"], place: "广东广州（今广州）", state: "清", sources: ["梁发《劝世良言》","（英）韩山文《太平天国起义记》","罗尔纲《太平天国史纲》"], tags: ["劝世良言","太平天国"] }, related: ["cn--1823--s01"] },
  { id: "cn--1834--p01", track: "cn", year: 1834, yearApprox: false, dim: "politics", weight: 3, title: "律劳卑事件", summary: "商务监督以平礼投书，粤海遂启兵端。", detail: { background: "1833年英国议会派驻粤商务监督，次年撤销东印度公司对华贸易专利权，欲以官员直接交涉取代行商居间。", process: "1834年7月首任监督律劳卑不循「夷目」旧例，以平等官礼直赴粤海关与大衙门投递公文，两广总督卢坤依行商封舱之例停止贸易；律劳卑调兵船两艘闯入虎门，与炮台互击，旋因供应断绝退泊澳门，10月病卒。", impact: "此为「夷目—行商」体制与近代使节制度冲突之第一回合：英商由此相信兵船可得口岸之利，粤省与朝廷则确信封舱停市足以制夷，双方各据此次经验作主战之判断，其认识上的错位至1840年遂以战争结算。", figures: ["律劳卑","卢坤"], place: "广州、澳门（今广州、澳门）", state: "清", sources: ["《（道光）筹办夷务始末》道光朝卷一","马士《中华帝国对外关系史》卷一","魏源《道光洋艘征抚记》"], tags: ["律劳卑","中英"] }, related: ["cn--1757--e01", "cn--1839--p01"] },
  { id: "cn--1835--e01", track: "cn", year: 1835, yearApprox: false, dim: "economy", weight: 3, title: "册报民数逾四万万", summary: "七十年间倍增，人地之势至此极。", detail: { background: "雍正摊丁入亩、乾隆通计民数以后，丁口隐匿日少，湖广、川陕、西南山区续垦不辍。", process: "1835年（道光十五年）户部汇各省册报民数逾四万万，较1762年之二万七千九百余万口几于倍增；同期册报田亩仅由七百余万顷增至七百九十余万顷，人均田亩由三亩余降至不足二亩。", impact: "人口压力成为道光朝一切内政之背景：垦殖过界而山洪、河患随之，米贵、钱贱、漕艰、匪多，游民与教门在川楚陕边省再生；现代学者推定1840年实际人口约在四万万至四万万二千万之间，与册报相去未远，此数亦为中外比较时中国传统经济总量之最盛与转折点。", figures: ["户部","旻宁"], place: "京师（今北京）", state: "清", sources: ["《（道光）东华录》户部汇题","《清朝续文献通考·户口》","何炳棣《中国人口研究》"], tags: ["人口","人地"] }, related: ["cn--1762--i01", "cn--1823--e01"] },
  { id: "cn--1836--e01", track: "cn", year: 1836, yearApprox: false, dim: "economy", weight: 4, title: "银贵钱贱与白银外流", summary: "银出而钱贱，农民完赋暗增三成。", detail: { background: "乾隆末以后英人以印度棉花、鸦片易华之茶丝，贸易由出超转而入超，内地钱价日跌。", process: "1836年（道光十六年）太常寺卿许乃藻奏请弛鸦片之禁，朝议纷起；据黄爵滋1838年奏疏所称，道光三年以前岁漏银数百万两，其后岁增至千万以上，是时一年之漏已不下一千数百余万两。京师钱价则由嘉庆初每两易钱一千一二百文，跌到道光中叶之一千六百文上下。", impact: "田赋以银起科而小民以钱完纳，银贵则本色暗增，州县火耗与亏空愈重，逋欠日积；货币失衡于是由商情问题变为财政与统治问题，严禁、弛禁、改币、筹银诸论并起，构成鸦片战争前十年朝政之中心议题。", figures: ["许乃藻","黄爵滋"], place: "京师、广东（今北京、广州）", state: "清", sources: ["《（道光）筹办夷务始末》道光朝卷九","杨端六《清代货币金融史稿》","《清宣宗实录》卷二八二"], tags: ["银荒","鸦片"] }, related: ["cn--1838--p01", "cn--1835--e01"] },
  { id: "cn--1838--p01", track: "cn", year: 1838, yearApprox: false, dim: "politics", weight: 4, title: "严禁与弛禁之争", summary: "一疏定国策，林则徐奉使赴粤。", detail: { background: "白银外流既久，言官与封疆于禁烟之方各有主见，弛禁之议一度得势。", process: "1838年（道光十八年）六月鸿胪寺卿黄爵滋上《严塞漏卮以培国本疏》，请予吸食者一年之限、逾期重以其罪；直隶总督琦善、湖广总督林则徐等先后复奏，则徐谓「若无外来之货，漏卮何自而多」，主张先绝来源。宣宗命各省将军督抚一体详议，遂定严禁之策。", impact: "此议使禁烟自地方查拿上升为国家政策，十二月即命林则徐为钦差大臣赴粤查办；朝中弛禁之论渐息，然朝廷于海防、外情与兵备全无布置，「禁烟」与「驭夷」二事自此纠缠不可分，次年即有缴烟、封舱与九龙、穿鼻之战。", figures: ["黄爵滋","林则徐","琦善"], place: "京师（今北京）", state: "清", sources: ["《（道光）筹办夷务始末》道光朝卷三","《林则徐集·奏稿》","《清宣宗实录》卷三一六"], tags: ["禁烟","朝议"] }, related: ["cn--1836--e01", "cn--1839--p01"] },
  { id: "cn--1839--e01", track: "cn", year: 1839, yearApprox: false, dim: "economy", weight: 3, title: "封舱与中英贸易断绝", summary: "一市停顿，粤省十行生计俱蹙。", detail: { background: "1839年7月尖沙嘴村民林维喜被英水手殴毙，义律拒不交出凶犯，自设法庭处罚数人。", process: "林则徐以断绝供应相绳，7月尽封澳门夷馆、驱英商于海面，并停止中英贸易，10月义律再求开市不得；茶、丝、棉花出口为之中歇，粤海关税短绌，通事、买办、舵工、搬运与十三行铺户失业者数万计，12月初以英商具结认罪为条件暂复贸易。", impact: "贸易停顿数月使中英双方皆尝其痛：粤省财政与市肆震动，英商则转由澳门、舟山与快艇私运棉、烟，白银外流未止。此事表明广州体制已不能同时驾驭执法与通商，其后《南京条约》之五口并开与协定税则，正是以破坏一口通商为其目标。", figures: ["林则徐","义律"], place: "广东广州、澳门（今广州、澳门）", state: "清", sources: ["《（道光）筹办夷务始末》道光朝卷一八","《林则徐日记》","《华洋贸易情形论略》各关册报"], tags: ["封舱","贸易"] }, related: ["cn--1757--e01", "cn--1839--p01"] },
  { id: "cn--1839--m01", track: "cn", year: 1839, yearApprox: false, dim: "military", weight: 3, title: "九龙、穿鼻之战", summary: "兵船不敌蒸汽舰，奏报犹称叠胜。", detail: { background: "义律以断绝给养与具结未成，请派兵船护商；林则徐、关天培在尖沙嘴、官涌增炮台、设木筏火船。", process: "1839年9月4日英船与巡船九龙海面互击，是为「九龙之战」；11月3日义律率舰至穿鼻洋，击沉、重创清拖罟、艇船数艘；随后英船连日进犯官涌炮台，清军凭险回击，双方各奏胜捷，英方记其员兵无阵亡者，清军死伤数十人至百余人之说互异。", impact: "木质风帆师船与前装炮不能敌西方蒸汽兵船与臼炮，差距自此显而不为朝廷所知；广东奏报多称「叠次获胜」「夷船焚溺」，庙算由误判而定，主剿、主抚往复于枢廷。林则徐虽译《四洲志》、访购船炮，见识未及转为一军之制，五年后之战遂以割地赔款结。", figures: ["关天培","义律","林则徐"], place: "广东九龙、穿鼻洋（今香港、珠江口）", state: "清", sources: ["《（道光）筹办夷务始末》道光朝卷一四","《林文忠公政书》","马士《中华帝国对外关系史》卷一"], tags: ["海战","中西军备"] }, related: ["cn--1839--p02", "cn--1834--p01"] },
  { id: "cn--1839--p01", track: "cn", year: 1839, yearApprox: false, dim: "politics", weight: 4, title: "林则徐使粤查烟", summary: "钦差至粤，限期尽缴烟土。", detail: { background: "1838年12月（道光十八年十一月）命湖广总督林则徐为钦差大臣，赴粤查办海口禁烟事宜。", process: "1839年3月10日林则徐抵广州，与两广总督邓廷桢、水师提督关天培筹海防，谕各国商人限期呈缴鸦片并具「永不夹带鸦片来粤」之结，且自誓「若鸦片一日未绝，本大臣一日不回」；英商务监督义律令英商缴烟而由英政府担其值。", impact: "至四月先后收鸦片二万余箱，美商、荷商亦相继呈缴；查禁由内地吸食推至海口来源，同时把贸易停止与外交对抗系于一处，广东中英关系自此再无回圜余地，为五个月后之军事冲突与1840年之战争直接铺路。", figures: ["林则徐","义律","关天培"], place: "广东广州（今广州）", state: "清", sources: ["《林则徐集·谕各国夷人呈缴烟土稿》","《（道光）筹办夷务始末》道光朝卷七","《林则徐日记》"], tags: ["禁烟","钦差"] }, related: ["cn--1838--p01", "cn--1839--p02"] },
  { id: "cn--1839--p02", track: "cn", year: 1839, yearApprox: false, dim: "politics", weight: 5, title: "虎门销烟", summary: "海水池化烟二十三日，外人往观。", detail: { background: "广州所收各国烟土分贮十三行仓馆，林则徐奏准于虎口临海筑池化销，以示共见共闻。", process: "1839年6月3日至25日在虎门镇海台旁之销化池，以盐卤投池、继以生石灰，随潮冲洗，凡二十余日，将所缴鸦片二万零二百八十三箱（一说英美各国合计二万一千一百九十八箱）销化净尽，奏报重量有二百零二万四千余斤、二百三十七万六千余斤两说，折银自九百余万两至二千余万两诸说不一；在澳英商、传教士与粤省士商往观者相属。", impact: "以公开程序与外人观礼销毁毒品，为近代世界禁毒史上之大事；英国政府与印粤散商以「保护财产」相胁，广州西商联名致书巴麦尊主战，1840年6月懿律率舰北犯，第一次鸦片战争起。此事在后世被反复征引，成为关于主权、贸易与毒品三者关系之公共记忆的起点。", figures: ["林则徐","邓廷桢"], place: "广东虎门（今东莞虎门）", state: "清", sources: ["《林则徐奏稿·会奏销化鸦片完竣折》","《（道光）筹办夷务始末》道光朝卷一三","马士《中华帝国对外关系史》卷一"], tags: ["虎门销烟","禁烟"] }, related: ["cn--1839--p01", "cn--1839--m01", "world--1839--p01"] },
];
